// NEET UG Biology: Respiration in plants (NCERT Class 11, Chapter 12). All questions original fibub work.
import { pick, int, choose, fmt, shuffleOpts, numOpts, g } from '../_entrance.js';

const E = ['neet'];
const items = [];
const groups = {};
let n = 0, pos = 0;
const POS = [2, 0, 3, 1];
const nid = () => `pr-${String(++n).padStart(3, '0')}`;
const AR = ['Both A and R are true and R is the correct explanation of A', 'Both A and R are true but R is not the correct explanation of A', 'A is true but R is false', 'A is false but R is true'];
const ST = ['Both Statement I and Statement II are correct', 'Both Statement I and Statement II are incorrect', 'Statement I is correct but Statement II is incorrect', 'Statement I is incorrect but Statement II is correct'];
function mc(level, sub, q, correct, wrongs, sol, trap, format = 'single') {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format, exams: E, sub, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function asr(level, sub, A, R, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'assertion', exams: E, sub, q: `<b>Assertion (A):</b> ${A}<br><b>Reason (R):</b> ${R}`, options: AR, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function stm(level, sub, s1, s2, ans, sol, trap) {
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: E, sub, q: `<b>Statement I:</b> ${s1}<br><b>Statement II:</b> ${s2}`, options: ST, answer: ans, sol, ...(trap ? { trap } : {}) });
}
function match(level, sub, key, title, list1, list2, correct, wrongs, sol, trap) {
  groups[key] = { title, list1, list2 };
  const p = POS[pos++ % 4];
  const options = [...wrongs]; options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: E, sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function pass(key, title, passage) { groups[key] = { title, passage }; }
function pq(key, level, sub, q, correct, wrongs, sol, trap) {
  const p = POS[pos++ % 4];
  const options = [...wrongs];
  options.splice(p, 0, correct);
  items.push({ id: nid(), type: 'mcq', level, format: 'passage', exams: E, sub, group: key, q, options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function nat(level, sub, q, answer, sol, trap, unit) {
  items.push({ id: nid(), type: 'nat', level, format: 'integer', exams: E, sub, q, answer, tol: 0, ...(unit ? { unit } : {}), sol, ...(trap ? { trap } : {}) });
}
// ---------------------------------------------------------------- Level 1
mc(1, 'basics', 'The breakdown of food to release energy in the cell, with the energy stored as ATP, is called', 'cellular respiration', ['photosynthesis', 'transpiration', 'translocation'], 'In respiration, the C–C bonds of organic compounds are broken and the energy is trapped in ATP.');
mc(1, 'basics', 'ATP is often called the', 'energy currency of the cell', ['genetic material', 'structural protein', 'plant hormone'], 'The energy released in respiration is stored in the high-energy bonds of ATP, which is spent when work is to be done.');
mc(1, 'basics', 'The usual respiratory substrate in plants is', 'carbohydrate', ['protein', 'nucleic acid', 'vitamin'], 'Carbohydrates, mostly glucose, are the main substrate. Fats and proteins can also be used.');
mc(1, 'basics', 'Plants do not have special organs for gas exchange like lungs because', 'each part takes in its own O<sub>2</sub> and releases CO<sub>2</sub>, and the gas needs are low', ['they do not respire', 'they use only fermentation', 'they have gills'], 'Each plant part manages its own gas exchange. The demand for gas exchange is much lower than in animals.');
mc(1, 'glycolysis', 'Glycolysis takes place in the', 'cytoplasm', ['mitochondrial matrix', 'inner mitochondrial membrane', 'chloroplast stroma'], 'Glycolysis is the first step of all respiration, in the cytoplasm of every living cell.');
mc(1, 'glycolysis', 'The end product of glycolysis from one glucose is', 'two molecules of pyruvic acid', ['one molecule of pyruvic acid', 'two molecules of acetyl CoA', 'two molecules of CO<sub>2</sub>'], 'The 6-carbon glucose is converted into two 3-carbon pyruvic acid molecules.');
mc(1, 'glycolysis', 'The scheme of glycolysis was given by', 'Embden, Meyerhof and Parnas', ['Calvin, Benson and Bassham', 'Hatch and Slack', 'Krebs and Johnson'], 'It is also called the EMP pathway.');
mc(1, 'glycolysis', 'In glycolysis the net gain of ATP per glucose is', '2', ['4', '8', '38'], 'Four ATP are made and two are spent, so the net gain is 2 ATP.');
mc(1, 'fermentation', 'In yeast, anaerobic respiration converts pyruvic acid into', 'ethanol and CO<sub>2</sub>', ['lactic acid only', 'acetyl CoA and CO<sub>2</sub>', 'glucose and O<sub>2</sub>'], 'Pyruvic acid decarboxylase and alcohol dehydrogenase give ethanol and CO<sub>2</sub>.');
mc(1, 'fermentation', 'In our muscles, pyruvic acid is turned to lactic acid when', 'oxygen is in short supply', ['there is too much oxygen', 'glucose is absent', 'ATP is in excess'], 'Lactate dehydrogenase reduces pyruvic acid to lactic acid when O<sub>2</sub> is low.');
mc(1, 'Krebs cycle', 'The Krebs cycle takes place in the', 'mitochondrial matrix', ['cytoplasm', 'inner membrane of the mitochondrion', 'nucleus'], 'The enzymes of the cycle, except succinate dehydrogenase, are in the matrix.');
mc(1, 'Krebs cycle', 'Acetyl CoA enters the Krebs cycle by combining with', 'oxaloacetic acid', ['pyruvic acid', 'succinic acid', 'citric acid'], 'Acetyl CoA (2C) + OAA (4C) → citric acid (6C).');
mc(1, 'Krebs cycle', 'The first compound formed in the Krebs cycle is', 'citric acid', ['isocitric acid', 'malic acid', 'fumaric acid'], 'It is also called the citric acid cycle or TCA cycle, as the first product is a tricarboxylic acid.');
mc(1, 'ETS', 'The terminal electron acceptor in the electron transport system is', 'oxygen', ['NAD<sup>+</sup>', 'cytochrome c', 'water'], 'Oxygen takes electrons and protons and forms water.');
mc(1, 'ETS', 'The electron transport system is located in the', 'inner mitochondrial membrane', ['outer mitochondrial membrane', 'matrix', 'cytoplasm'], 'The complexes are in the inner membrane, which is folded into cristae.');
mc(1, 'RQ', 'The respiratory quotient is the ratio of', 'volume of CO<sub>2</sub> released to volume of O<sub>2</sub> consumed', ['volume of O<sub>2</sub> consumed to CO<sub>2</sub> released', 'ATP made to glucose used', 'NADH to FADH<sub>2</sub>'], 'RQ = CO<sub>2</sub> evolved ÷ O<sub>2</sub> consumed.');
mc(1, 'RQ', 'The RQ when glucose is the respiratory substrate is', '1', ['0.7', '0.9', 'infinity'], 'C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub> → 6CO<sub>2</sub> + 6H<sub>2</sub>O. So 6 ÷ 6 = 1.');
mc(1, 'amphibolic', 'The respiratory pathway is called amphibolic because it is involved in', 'both breakdown and building up of compounds', ['only breakdown', 'only synthesis', 'only gas exchange'], 'It gives energy (catabolism) and also supplies intermediates for synthesis (anabolism).');

// ---------------------------------------------------------------- Level 2
mc(2, 'basics', 'How does the release of energy in respiration differ from burning?', 'Energy is released slowly in many steps in respiration', ['Energy is released all at once as heat in respiration', 'Respiration needs a flame to start', 'Burning releases energy in many enzyme-controlled steps'], 'Respiration is an enzyme-controlled, stepwise oxidation. Burning is a rapid, single-step process.');
mc(2, 'basics', 'The energy stored in one mole of ATP bond that is released on hydrolysis is about', '30.5 kJ', ['3.05 kJ', '305 kJ', '2870 kJ'], 'NCERT gives 30.5 kJ/mol. The figure 2870 kJ is the energy of oxidation of one mole of glucose.');
mc(2, 'glycolysis', 'Sucrose enters glycolysis after being split by the enzyme', 'invertase', ['amylase', 'hexokinase', 'lipase'], 'Sucrose is hydrolysed to glucose and fructose by invertase. Both are phosphorylated to enter glycolysis.');
mc(2, 'glycolysis', 'In the first step of glycolysis, glucose is changed to glucose 6-phosphate by', 'hexokinase, using ATP', ['aldolase, using NAD<sup>+</sup>', 'enolase, giving ATP', 'isomerase, using ATP'], 'Hexokinase transfers a phosphate from ATP to glucose.');
mc(2, 'glycolysis', 'The two steps in which ATP is used in glycolysis are', 'glucose to G6P and fructose 6-phosphate to fructose 1,6-bisphosphate', ['PEP to pyruvate and BPGA to 3-PGA', 'G6P to F6P and 3-PGA to 2-PGA', 'PGAL to BPGA and DHAP to PGAL'], 'Two ATP are invested, in the two phosphorylation steps.');
mc(2, 'glycolysis', 'The six-carbon sugar bisphosphate formed in glycolysis splits into', 'DHAP and PGAL', ['two pyruvic acid molecules', 'two acetyl CoA molecules', 'PEP and BPGA'], 'Fructose 1,6-bisphosphate is split by aldolase into dihydroxyacetone phosphate and 3-phosphoglyceraldehyde (PGAL).');
mc(2, 'glycolysis', 'ATP is produced by substrate-level phosphorylation in glycolysis in the conversion of', 'BPGA to 3-PGA and PEP to pyruvic acid', ['glucose to G6P', 'F6P to fructose 1,6-bisphosphate', 'PGAL to BPGA'], 'Two ATP per 3-carbon unit are made in these two steps, so 4 ATP per glucose.');
mc(2, 'glycolysis', 'The step in which NADH is formed in glycolysis is', 'oxidation and phosphorylation of PGAL to BPGA', ['conversion of PEP to pyruvate', 'conversion of glucose to G6P', 'conversion of DHAP to F6P'], 'PGAL is oxidised, NAD<sup>+</sup> is reduced to NADH + H<sup>+</sup>, and an inorganic phosphate is added.');
mc(2, 'glycolysis', 'Net products of glycolysis per glucose are', '2 pyruvic acid, 2 ATP and 2 NADH', ['1 pyruvic acid, 4 ATP and 1 NADH', '2 pyruvic acid, 4 ATP and 2 FADH<sub>2</sub>', '2 pyruvic acid, 2 ATP and 6 NADH'], 'Gross ATP 4, minus 2 used = 2 net. 2 PGAL give 2 NADH.', 'The 4 ATP is the gross figure.');
mc(2, 'fermentation', 'Fermentation in yeast releases', 'much less energy than aerobic respiration', ['more energy than aerobic respiration', 'no energy at all', 'the same energy as aerobic respiration'], 'Only 2 ATP net per glucose, from glycolysis. Most energy remains in the ethanol.');
mc(2, 'fermentation', 'Yeast poisons itself in fermentation when the alcohol concentration reaches about', '13 per cent', ['3 per cent', '30 per cent', '60 per cent'], 'NCERT states that yeast is killed at about 13 per cent alcohol.');
mc(2, 'fermentation', 'The enzymes that convert pyruvic acid into ethanol are', 'pyruvic acid decarboxylase and alcohol dehydrogenase', ['lactate dehydrogenase and hexokinase', 'citrate synthase and aconitase', 'RuBisCO and PEPcase'], 'Decarboxylase removes CO<sub>2</sub> to give acetaldehyde. Alcohol dehydrogenase reduces it to ethanol, using NADH.');
mc(2, 'fermentation', 'Why is NADH reoxidised in fermentation?', 'to regenerate NAD<sup>+</sup> so that glycolysis can go on', ['to make ATP in the ETS', 'to form glucose', 'to fix CO<sub>2</sub>'], 'Glycolysis needs NAD<sup>+</sup>. Without oxygen, the NADH is oxidised by pyruvate or acetaldehyde.');
mc(2, 'link reaction', 'Pyruvic acid enters the mitochondrion and is changed to acetyl CoA by', 'oxidative decarboxylation', ['reduction', 'phosphorylation only', 'hydrolysis'], 'The reaction releases CO<sub>2</sub>, makes NADH, and adds CoA. It needs the pyruvate dehydrogenase complex.');
mc(2, 'link reaction', 'The link reaction needs which cofactors?', 'NAD<sup>+</sup>, coenzyme A and Mg<sup>2+</sup>', ['FAD and ADP', 'NADP<sup>+</sup> and Fe<sup>2+</sup>', 'ATP and Cu<sup>2+</sup>'], 'The pyruvate dehydrogenase complex uses NAD<sup>+</sup>, CoA and Mg<sup>2+</sup>.');
mc(2, 'link reaction', 'The link reaction for one glucose gives', '2 acetyl CoA, 2 CO<sub>2</sub> and 2 NADH', ['1 acetyl CoA, 1 CO<sub>2</sub> and 1 NADH', '2 acetyl CoA, 2 FADH<sub>2</sub> and 2 ATP', '6 CO<sub>2</sub>'], 'Two pyruvic acids arise from one glucose, so the reaction runs twice.');
mc(2, 'Krebs cycle', 'In one turn of the Krebs cycle, the number of NADH, FADH<sub>2</sub> and GTP/ATP formed are', '3, 1 and 1', ['2, 2 and 1', '3, 2 and 2', '4, 1 and 1'], 'Three NADH (isocitrate, α-ketoglutarate, malate), one FADH<sub>2</sub> (succinate) and one GTP (succinyl CoA).');
mc(2, 'Krebs cycle', 'The number of CO<sub>2</sub> molecules released in one turn of the Krebs cycle is', 'two', ['one', 'three', 'six'], 'Decarboxylation at isocitrate to α-ketoglutarate, and α-ketoglutarate to succinyl CoA.');
mc(2, 'Krebs cycle', 'The 5-carbon compound of the Krebs cycle is', 'α-ketoglutaric acid', ['isocitric acid', 'succinic acid', 'citric acid'], 'Citric acid (6C) → isocitric acid (6C) → α-ketoglutaric acid (5C) → succinyl CoA (4C).');
mc(2, 'Krebs cycle', 'FADH<sub>2</sub> is formed in the Krebs cycle during the change of', 'succinic acid to fumaric acid', ['fumaric acid to malic acid', 'malic acid to OAA', 'citric acid to isocitric acid'], 'Succinate dehydrogenase, which is in the inner membrane, uses FAD as the acceptor.');
mc(2, 'Krebs cycle', 'Substrate-level phosphorylation in the Krebs cycle occurs during the conversion of', 'succinyl CoA to succinic acid', ['succinic acid to fumaric acid', 'malic acid to OAA', 'isocitrate to α-ketoglutarate'], 'GDP is phosphorylated to GTP, which makes ATP.');
mc(2, 'ETS', 'Complex I of the ETS is', 'NADH dehydrogenase', ['succinate dehydrogenase', 'cytochrome c oxidase', 'ATP synthase'], 'Complex I takes electrons from NADH. Complex II is succinate dehydrogenase.');
mc(2, 'ETS', 'Electrons from FADH<sub>2</sub> enter the ETS through', 'complex II (succinate dehydrogenase)', ['complex I', 'complex IV', 'ATP synthase'], 'FADH<sub>2</sub> gives electrons to ubiquinone through complex II, so they skip complex I.');
mc(2, 'ETS', 'Ubiquinone (coenzyme Q) is', 'a mobile carrier that receives electrons from complexes I and II', ['a part of ATP synthase', 'the terminal acceptor of electrons', 'a protein in the matrix only'], 'Ubiquinone passes the electrons to complex III.');
mc(2, 'ETS', 'Cytochrome c is a', 'small protein attached to the outer surface of the inner membrane, between complexes III and IV', ['large complex that makes ATP', 'a carrier in the matrix', 'an enzyme of glycolysis'], 'Cyt c is a mobile carrier. It moves electrons from complex III to complex IV.');
mc(2, 'ETS', 'Complex IV (cytochrome c oxidase) contains', 'cytochromes a and a<sub>3</sub> and two copper centres', ['FAD and Fe–S only', 'chlorophyll', 'F<sub>0</sub> and F<sub>1</sub>'], 'It passes electrons to O<sub>2</sub>, which is reduced to water.');
mc(2, 'ETS', 'ATP synthase (complex V) has two parts called', 'F<sub>1</sub> and F<sub>0</sub>', ['CF<sub>1</sub> and CF<sub>0</sub> only in plants', 'P680 and P700', 'α and β only'], 'F<sub>1</sub> is the headpiece with the site for ATP synthesis. F<sub>0</sub> is the channel in the membrane. (In chloroplasts the same parts are named CF<sub>1</sub> and CF<sub>0</sub>.)');
mc(2, 'ETS', 'In oxidative phosphorylation, protons are pumped into the', 'intermembrane space', ['matrix', 'cytoplasm', 'stroma'], 'The gradient is across the inner membrane. Protons flow back into the matrix through F<sub>0</sub>, and ATP is made.');
mc(2, 'ETS', 'The number of ATP made from one NADH in the ETS (NCERT count) is', '3', ['2', '1', '4'], 'FADH<sub>2</sub> gives 2 ATP in the NCERT count.');
mc(2, 'RQ', 'RQ is less than 1 when the respiratory substrate is', 'fat', ['carbohydrate', 'organic acid', 'pyruvic acid'], 'Fats have little oxygen in them, so more O<sub>2</sub> is used. CO<sub>2</sub> released is less than O<sub>2</sub> used.');
mc(2, 'RQ', 'The RQ of tripalmitin is about', '0.7', ['1.0', '0.9', '1.4'], '2(C<sub>51</sub>H<sub>98</sub>O<sub>6</sub>) + 145O<sub>2</sub> → 102CO<sub>2</sub> + 98H<sub>2</sub>O. So 102 ÷ 145 ≈ 0.7.');
mc(2, 'RQ', 'The RQ when proteins are the substrate is about', '0.9', ['0.7', '1', '1.5'], 'Proteins give an RQ near 0.9.');
mc(2, 'RQ', 'In anaerobic respiration with CO<sub>2</sub> released and no O<sub>2</sub> consumed, the RQ is', 'infinity', ['zero', '1', '0.7'], 'RQ = CO<sub>2</sub>/O<sub>2</sub>, and O<sub>2</sub> is zero.');
mc(2, 'amphibolic', 'In respiration, fatty acids enter the pathway as', 'acetyl CoA', ['pyruvic acid', 'PGAL', 'OAA'], 'Fatty acids are broken into acetyl CoA, which enters the Krebs cycle. Glycerol enters as PGAL.');
mc(2, 'amphibolic', 'Glycerol from fat enters the respiratory pathway as', 'PGAL', ['acetyl CoA', 'succinyl CoA', 'α-ketoglutarate'], 'Glycerol is changed to PGAL, and it enters glycolysis.');
mc(2, 'amphibolic', 'In respiration, amino acids from proteins enter after', 'deamination, at pyruvic acid, acetyl CoA or a Krebs cycle intermediate', ['photolysis', 'carboxylation by RuBisCO', 'hydrolysis of ATP'], 'Amino acids lose their amino group first, and the carbon skeleton joins the pathway at different places.');

// ---------------------------------------------------------------- Level 3
mc(3, 'ATP accounting', 'The total ATP gain from complete aerobic oxidation of one glucose, by the NCERT count (3 per NADH, 2 per FADH<sub>2</sub>), is', '38', ['36', '30', '32'], 'Glycolysis: 2 ATP + 2 NADH (6) = 8. Link reaction: 2 NADH = 6. Krebs: 2 ATP + 6 NADH (18) + 2 FADH<sub>2</sub> (4) = 24. Total = 8 + 6 + 24 = 38.', 'Modern counts give about 30 to 32, but NCERT gives 38.');
mc(3, 'ATP accounting', 'Of the 38 ATP from one glucose in aerobic respiration, the number made by substrate-level phosphorylation is', '4', ['2', '6', '38'], '2 net in glycolysis and 2 in the Krebs cycle. The other 34 come from oxidative phosphorylation.');
mc(3, 'ATP accounting', 'The number of ATP made by oxidative phosphorylation from one glucose (NCERT count) is', '34', ['38', '4', '30'], '10 NADH × 3 = 30 and 2 FADH<sub>2</sub> × 2 = 4. So 34.');
mc(3, 'ATP accounting', 'For one glucose, how many NADH are formed in total in aerobic respiration?', '10', ['8', '12', '6'], '2 in glycolysis, 2 in the link reaction, 6 in the Krebs cycle = 10.');
mc(3, 'ATP accounting', 'How many FADH<sub>2</sub> are made from one glucose in aerobic respiration?', '2', ['1', '4', '6'], 'One FADH<sub>2</sub> per turn of the Krebs cycle, and two turns per glucose.');
mc(3, 'ATP accounting', 'How many CO<sub>2</sub> are released in the link reaction and Krebs cycle together, for one glucose?', '6', ['2', '4', '12'], 'Link reaction gives 2. The Krebs cycle gives 2 per turn, so 4. Total 6.');
mc(3, 'ATP accounting', 'Which step produces ATP without oxygen?', 'Glycolysis', ['ETS', 'Oxidative phosphorylation', 'Chemiosmosis in mitochondria'], 'Glycolysis makes ATP by substrate-level phosphorylation, with no O<sub>2</sub> needed.');
mc(3, 'ATP accounting', 'The ATP from one pyruvic acid entering the mitochondrion and being completely oxidised is (NCERT count)', '15', ['12', '19', '38'], 'Link reaction: 1 NADH (3). Krebs cycle: 3 NADH (9), 1 FADH<sub>2</sub> (2), 1 ATP = 12. Total = 15.', 'Two pyruvic acids give 30, which with 8 from glycolysis totals 38.');
mc(3, 'fermentation', 'Compared with aerobic respiration, the energy trapped as ATP in fermentation is', 'about 2 ATP against 38 per glucose', ['about 18 ATP against 38', 'about 36 ATP against 38', 'the same'], 'Only glycolysis supplies ATP in fermentation.');
mc(3, 'fermentation', 'Which cells can use lactic acid fermentation?', 'Skeletal muscle cells during heavy exercise', ['Yeast cells', 'Guard cells in light', 'Root hair cells in oxygen-free water only'], 'Lactate dehydrogenase works in muscle when oxygen is short. Yeast gives ethanol.');
mc(3, 'fermentation', 'Which is NOT a point of difference between fermentation and aerobic respiration?', 'Both start with glycolysis', ['ATP yield is lower in fermentation', 'Oxygen is needed in aerobic respiration only', 'Fermentation ends with incomplete oxidation of glucose'], 'Both use glycolysis, so that is a common point, not a difference.');
mc(3, 'fermentation', 'In ethanol fermentation, the 2-carbon compound that is reduced to ethanol is', 'acetaldehyde', ['acetic acid', 'acetyl CoA', 'pyruvic acid'], 'Pyruvic acid loses CO<sub>2</sub> to give acetaldehyde, which is reduced by NADH.');
mc(3, 'Krebs cycle', 'One of these is a decarboxylation step in the Krebs cycle.', 'Isocitric acid to α-ketoglutaric acid', ['Citric acid to isocitric acid', 'Succinic acid to fumaric acid', 'Fumaric acid to malic acid'], 'CO<sub>2</sub> is lost at isocitrate to α-ketoglutarate, and at α-ketoglutarate to succinyl CoA.');
mc(3, 'Krebs cycle', 'The Krebs cycle is a cycle because', 'oxaloacetic acid is regenerated at the end', ['acetyl CoA is regenerated', 'pyruvic acid is regenerated', 'NADH is regenerated'], 'Malic acid is oxidised to OAA, which can accept another acetyl CoA.');
mc(3, 'Krebs cycle', 'Which Krebs cycle enzyme is found in the inner membrane?', 'Succinate dehydrogenase', ['Citrate synthase', 'Malate dehydrogenase', 'Aconitase'], 'The others are in the matrix. Succinate dehydrogenase is also complex II of the ETS.');
mc(3, 'Krebs cycle', 'How many NADH are formed in the Krebs cycle for two acetyl CoA?', '6', ['3', '4', '8'], 'Three per turn, and two turns.');
mc(3, 'Krebs cycle', 'Which is the correct order?', 'Citrate → isocitrate → α-ketoglutarate → succinyl CoA → succinate → fumarate → malate → OAA', ['Citrate → α-ketoglutarate → isocitrate → succinate → malate → fumarate → OAA', 'OAA → succinate → fumarate → citrate', 'Citrate → succinyl CoA → α-ketoglutarate → malate'], 'This is the standard sequence of the cycle.');
mc(3, 'link reaction', 'The link reaction takes place in', 'the mitochondrial matrix', ['the cytoplasm', 'the inner membrane', 'the intermembrane space'], 'Pyruvic acid is moved from the cytoplasm into the matrix.');
mc(3, 'ETS', 'The ETS shows that', 'electrons pass in order from carriers of lower to higher redox potential, ending at O<sub>2</sub>', ['electrons move from O<sub>2</sub> to NADH', 'each carrier makes ATP directly', 'protons move to the matrix as electrons are carried'], 'The flow is downhill. The energy released pumps protons out of the matrix.');
mc(3, 'ETS', 'Which complex pumps protons AND passes electrons to cytochrome c?', 'Complex III', ['Complex II', 'ATP synthase', 'Complex IV only'], 'Complex III (cytochrome bc<sub>1</sub>) takes electrons from ubiquinone and passes them to cyt c, pumping protons.', 'Complex II does not pump protons.');
mc(3, 'ETS', 'Protons accumulate in the intermembrane space and flow into the matrix through', 'the F<sub>0</sub> channel of ATP synthase', ['the F<sub>1</sub> headpiece', 'cytochrome c', 'complex II'], 'F<sub>0</sub> is the channel. The flow makes F<sub>1</sub> change shape and make ATP.');
mc(3, 'ETS', 'Oxidative phosphorylation needs which of these?', 'Oxygen as the final electron acceptor and an intact inner membrane', ['Light and chlorophyll', 'Only matrix enzymes', 'Cytoplasmic enzymes of glycolysis only'], 'A closed inner membrane keeps the proton gradient. Oxygen allows the chain to keep running.');
mc(3, 'ETS', 'What is the role of oxygen in the ETS?', 'It takes electrons and protons to form water, so the chain can keep moving', ['It makes ATP directly', 'It carries electrons from NADH', 'It makes CO<sub>2</sub>'], 'Without O<sub>2</sub>, the carriers stay reduced and ATP synthesis stops.');
mc(3, 'RQ', 'An organic acid such as malic acid has an RQ', 'greater than one', ['less than one', 'equal to one', 'zero'], 'Organic acids have more oxygen than carbohydrate, so less O<sub>2</sub> is used. RQ is above 1.');
mc(3, 'RQ', 'In germinating castor seeds, where fats are the substrate, RQ is nearly', '0.7', ['1.0', '1.5', '0.1'], 'Fat is poor in oxygen, so a lot of O<sub>2</sub> is needed per CO<sub>2</sub> released.');
mc(3, 'RQ', 'A germinating seed uses 40 mL of O<sub>2</sub> and releases 28 mL of CO<sub>2</sub>. Its RQ is', '0.7', ['1.43', '1.0', '0.28'], 'RQ = 28 ÷ 40 = 0.7. This suggests fats.', 'Do not invert the ratio.');
mc(3, 'RQ', 'A pea seedling releases 60 mL of CO<sub>2</sub> and uses 60 mL of O<sub>2</sub>. The substrate is probably', 'carbohydrate', ['fat', 'protein', 'organic acid'], 'RQ = 1.');
mc(3, 'RQ', 'The RQ of a tissue is 1.33. The substrate is most likely', 'an organic acid', ['carbohydrate', 'a fat', 'a protein'], 'RQ above 1 indicates organic acids, or partly anaerobic respiration.');
mc(3, 'amphibolic', 'Which of these is an anabolic use of respiratory intermediates?', 'Acetyl CoA used to make fatty acids', ['Glucose broken down to pyruvic acid', 'Fatty acids broken down to acetyl CoA', 'Proteins hydrolysed to amino acids'], 'Using intermediates for synthesis is anabolism. The other three are catabolic.');
mc(3, 'amphibolic', 'Why is the respiratory pathway better called amphibolic than catabolic?', 'Its intermediates are also drawn off for making other compounds', ['It makes ATP', 'It needs oxygen', 'It uses enzymes'], 'Compounds like fatty acids and amino acids are made from intermediates.');
mc(3, 'amphibolic', 'A respiratory intermediate that would be drawn for the synthesis of amino acids is', 'α-ketoglutaric acid or OAA', ['ATP', 'water', 'NADH'], 'Keto acids pick up an amino group to give glutamic acid or aspartic acid.');
mc(3, 'mixed', 'Which one of these occurs in both photosynthesis and respiration?', 'Chemiosmotic ATP synthesis using a proton gradient', ['Fixation of CO<sub>2</sub>', 'Splitting of water', 'Glycolysis'], 'Both use ATP synthase driven by a proton gradient. Chloroplasts use light-driven electron flow.');
mc(3, 'mixed', 'Both chloroplast ATP synthase and mitochondrial ATP synthase have', 'a channel part in the membrane and a headpiece that makes ATP', ['a headpiece in the lumen', 'a headpiece in the intermembrane space', 'no proton channel'], 'The headpiece (F<sub>1</sub> or CF<sub>1</sub>) is on the side where ATP is made, the matrix or stroma.');
mc(3, 'mixed', 'During respiration the glucose carbon is', 'released as CO<sub>2</sub> in the link reaction and Krebs cycle', ['released as CO<sub>2</sub> in glycolysis', 'released as O<sub>2</sub>', 'stored as ATP'], 'Glycolysis releases no CO<sub>2</sub>. Decarboxylations are in the link reaction and Krebs cycle.');
asr(2, 'glycolysis', 'Glycolysis is the common first step of aerobic and anaerobic respiration.', 'It takes place in the cytoplasm and does not need oxygen.', 0, 'Because glycolysis needs no O<sub>2</sub>, it can go on under any condition, so R explains A.');
asr(3, 'ETS', 'Oxygen is needed for aerobic respiration.', 'Oxygen is the final acceptor of electrons in the ETS.', 0, 'Without a final acceptor, the chain stops, and NADH could not be reoxidised.');
asr(3, 'Krebs cycle', 'The Krebs cycle does not use oxygen directly, yet it stops without oxygen.', 'NAD<sup>+</sup> and FAD are regenerated only by the ETS, which needs O<sub>2</sub>.', 0, 'The cycle needs NAD<sup>+</sup> and FAD. Without oxygen, the ETS stops and these are not regenerated.');
asr(3, 'RQ', 'The RQ for fats is less than 1.', 'Fats contain less oxygen than carbohydrates for the same number of carbons.', 0, 'More O<sub>2</sub> is needed to oxidise them, so CO<sub>2</sub>/O<sub>2</sub> is below one.');
asr(3, 'fermentation', 'Fermentation gives much less ATP than aerobic respiration.', 'In fermentation, glucose is oxidised only partially.', 0, 'Most of the energy remains in ethanol or lactic acid, so R explains A.');
asr(3, 'amphibolic', 'The respiratory pathway is amphibolic.', 'Respiration gives both ATP and intermediates for synthesis.', 0, 'Catabolism gives energy and anabolism uses intermediates, which is what amphibolic means.');
asr(4, 'ETS', 'Cytochrome c is a mobile carrier of electrons.', 'It is a large integral protein complex of the inner membrane.', 2, 'It is a small peripheral protein on the outer surface of the inner membrane.');
asr(4, 'ATP accounting', 'Aerobic respiration gives 38 ATP by the NCERT count, of which most is made in the ETS.', 'ATP made in glycolysis is by oxidative phosphorylation.', 2, 'Glycolysis uses substrate-level phosphorylation, so R is false.');
asr(4, 'glycolysis', 'Glycolysis nets 2 ATP per glucose though 4 are formed.', 'Two ATP are used up in the early steps.', 0, 'The investment of 2 ATP in the first phosphorylations reduces the net gain.');
stm(2, 'glycolysis', 'Glycolysis occurs in the cytoplasm.', 'Glycolysis occurs only in the presence of oxygen.', 2, 'It does not need O<sub>2</sub>.');
stm(3, 'Krebs cycle', 'FADH<sub>2</sub> is made in the Krebs cycle.', 'NADH is made at 3 steps of one turn of the Krebs cycle.', 0, 'There are three NADH and one FADH<sub>2</sub> per turn. Both are correct.');
stm(3, 'ETS', 'Complex II is succinate dehydrogenase.', 'Complex IV is NADH dehydrogenase.', 2, 'Complex IV is cytochrome c oxidase. Complex I is NADH dehydrogenase.');
stm(3, 'link reaction', 'Link reaction releases CO<sub>2</sub>.', 'Link reaction occurs in the cytoplasm.', 2, 'It occurs in the matrix of the mitochondrion.');
stm(3, 'RQ', 'RQ of carbohydrates is one.', 'RQ of organic acids is less than one.', 2, 'It is greater than one for organic acids.');
stm(3, 'ATP accounting', 'Each NADH gives 3 ATP in the NCERT count.', 'Each FADH<sub>2</sub> gives 3 ATP in the NCERT count.', 2, 'FADH<sub>2</sub> gives 2 ATP.');
stm(3, 'fermentation', 'In lactic acid fermentation, CO<sub>2</sub> is released.', 'In alcohol fermentation, CO<sub>2</sub> is released.', 3, 'Lactic acid fermentation does not release CO<sub>2</sub> (pyruvate to lactate). Alcohol fermentation does.');
stm(4, 'amphibolic', 'Fatty acids enter the respiratory pathway as acetyl CoA.', 'Glycerol enters the pathway as acetyl CoA.', 2, 'Glycerol enters as PGAL.');
match(2, 'glycolysis', 'prm1', 'Respiratory step and product or site', ['A. Glycolysis', 'B. Link reaction', 'C. Krebs cycle', 'D. ETS'], ['p. Matrix, makes citric acid from OAA', 'q. Cytoplasm, glucose to pyruvic acid', 'r. Inner membrane, water formed', 's. Matrix, pyruvic acid to acetyl CoA'], 'A-q, B-s, C-p, D-r', ['A-s, B-q, C-p, D-r', 'A-q, B-s, C-r, D-p', 'A-p, B-q, C-s, D-r'], 'Glycolysis is cytoplasmic. The link reaction is in the matrix. The Krebs cycle starts with citrate in the matrix. The ETS makes water in the inner membrane.');
match(3, 'ETS', 'prm2', 'ETS component and role', ['A. Complex I', 'B. Complex II', 'C. Complex III', 'D. Complex IV'], ['p. Cytochrome c oxidase, reduces O<sub>2</sub>', 'q. NADH dehydrogenase', 'r. Succinate dehydrogenase', 's. Cytochrome bc<sub>1</sub> complex'], 'A-q, B-r, C-s, D-p', ['A-r, B-q, C-s, D-p', 'A-q, B-r, C-p, D-s', 'A-s, B-r, C-q, D-p'], 'I: NADH dehydrogenase. II: succinate dehydrogenase. III: bc<sub>1</sub>. IV: cytochrome c oxidase.');
match(3, 'RQ', 'prm3', 'Substrate and RQ', ['A. Glucose', 'B. Tripalmitin', 'C. Protein', 'D. Malic acid'], ['p. About 0.7', 'q. 1', 'r. About 0.9', 's. 1.33'], 'A-q, B-p, C-r, D-s', ['A-p, B-q, C-r, D-s', 'A-q, B-p, C-s, D-r', 'A-r, B-p, C-q, D-s'], 'Glucose 1, tripalmitin 0.7, proteins 0.9, malic acid 4 ÷ 3 = 1.33.');
match(4, 'Krebs cycle', 'prm4', 'Krebs cycle step and event', ['A. Isocitrate to α-ketoglutarate', 'B. Succinyl CoA to succinate', 'C. Succinate to fumarate', 'D. Malate to OAA'], ['p. FADH<sub>2</sub> is formed', 'q. NADH and CO<sub>2</sub>', 'r. GTP is formed', 's. NADH only'], 'A-q, B-r, C-p, D-s', ['A-s, B-r, C-p, D-q', 'A-q, B-p, C-r, D-s', 'A-q, B-r, C-s, D-p'], 'Isocitrate: NADH and CO<sub>2</sub>. Succinyl CoA: substrate-level GTP. Succinate: FADH<sub>2</sub>. Malate: NADH.');
pass('prp1', 'Passage: yeast in a flask', 'Yeast is added to a flask with glucose solution and sealed with a tube that dips into lime water. After some time, the lime water turns milky and a smell of alcohol is noticed. A second flask has the same mixture but is aerated with a stream of air. In this flask the yeast multiplies faster, with less alcohol formed.');
pq('prp1', 3, 'fermentation', 'The milky lime water shows that', 'CO<sub>2</sub> is released in the sealed flask', ['O<sub>2</sub> is released in the flask', 'glucose is turned into starch', 'ATP is released'], 'Lime water turns milky with CO<sub>2</sub>. In fermentation, pyruvic acid is decarboxylated.');
pq('prp1', 4, 'fermentation', 'The second flask makes less alcohol because', 'with O<sub>2</sub>, pyruvic acid is oxidised completely and more ATP is made', ['O<sub>2</sub> stops glycolysis', 'O<sub>2</sub> destroys the yeast', 'glucose cannot enter the cells in air'], 'With oxygen, pyruvic acid goes to the mitochondria for the link reaction, Krebs cycle and ETS. The ATP yield is much higher, so more growth.');
pass('prp2', 'Passage: seeds and gases', 'A set of seeds of three types, P, Q and R, is kept in closed respirometers with a KOH solution that absorbs CO<sub>2</sub>. The O<sub>2</sub> used in an hour is 50 mL for each type. In another set without KOH, the volume of gas changes by +0 mL for P, −15 mL for Q and +20 mL for R in an hour.');
pq('prp2', 4, 'RQ', 'The CO<sub>2</sub> released by seeds P, Q and R (in mL per hour) is', '50, 35 and 70', ['0, 15 and 20', '50, 65 and 30', '35, 50 and 70'], 'Without KOH, the volume change is CO<sub>2</sub> released minus O<sub>2</sub> used. P: 50 − 50 = 0 so CO<sub>2</sub> = 50. Q: −15 = CO<sub>2</sub> − 50 so CO<sub>2</sub> = 35. R: +20 so CO<sub>2</sub> = 70.');
pq('prp2', 4, 'RQ', 'The RQ values of P, Q and R are', '1.0, 0.7 and 1.4', ['1.0, 1.4 and 0.7', '0.7, 1.0 and 1.4', '1.4, 1.0 and 0.7'], 'RQ = CO<sub>2</sub> ÷ O<sub>2</sub> = 50/50, 35/50, 70/50.');
pq('prp2', 5, 'RQ', 'Q is likely to be rich in', 'fat', ['starch', 'organic acids', 'only protein'], 'RQ of 0.7 is the value for fats.');
pass('prp3', 'Passage: a blocked mitochondrion', 'A researcher adds a chemical that makes the inner mitochondrial membrane leaky to protons but does not block the electron carriers. Oxygen use rises sharply, but ATP formation falls to a very low level.');
pq('prp3', 4, 'ETS', 'The oxygen use rises because', 'electron flow continues freely without being held back by a proton gradient', ['ATP synthase is activated', 'glycolysis is blocked', 'NADH is no longer made'], 'The gradient normally slows electron flow. With a leaky membrane, flow runs on and the oxygen use rises.');
pq('prp3', 4, 'ETS', 'ATP formation falls because', 'there is no proton gradient to drive ATP synthase', ['the electron carriers are blocked', 'oxygen is lacking', 'glucose is absent'], 'ATP is made by flow of protons through F<sub>0</sub>. A leaky membrane loses the gradient. This is how an uncoupler acts.');

// ---------------------------------------------------------------- Level 4
mc(4, 'ATP accounting', 'A cell has used up its oxygen. Compared with the aerobic state, its ATP production per glucose falls from 38 to', '2', ['4', '8', '19'], 'Only glycolysis gives ATP when the ETS stops. The NADH of glycolysis is used to reduce pyruvate or acetaldehyde.');
mc(4, 'ATP accounting', 'Two glucose molecules are completely oxidised in a plant cell. How many NADH are formed in the mitochondrial matrix alone?', '16', ['20', '8', '12'], 'Per glucose: 2 (link) + 6 (Krebs) = 8 in the matrix. 2 glucose: 16. The glycolytic NADH is in the cytoplasm.', 'Remember glycolytic NADH is formed outside the mitochondrion.');
mc(4, 'ATP accounting', 'Which of these gives the greatest number of ATP per molecule (NCERT count)?', 'NADH from the Krebs cycle (3)', ['FADH<sub>2</sub> (2)', 'GTP from succinyl CoA (1)', 'Net ATP of one glycolysis step (1)'], 'NADH gives 3, FADH<sub>2</sub> 2, and substrate-level steps give 1 each.');
mc(4, 'ATP accounting', 'If the ATP yield from one mole of glucose is 38 and each ATP stores 30.5 kJ, the total energy trapped is', '1159 kJ', ['2870 kJ', '30.5 kJ', '116 kJ'], '38 × 30.5 = 1159 kJ. Glucose has 2870 kJ/mol, so about 40 per cent is trapped.');
mc(4, 'ATP accounting', 'How many ATP are made from one molecule of succinic acid fully oxidised to OAA (NCERT count)?', '5', ['3', '4', '6'], 'Succinate to fumarate gives FADH<sub>2</sub> (2). Malate to OAA gives NADH (3). Total 5.', 'Remember the FADH<sub>2</sub> counts only 2.');
mc(4, 'ATP accounting', 'One acetyl CoA entering the Krebs cycle gives, in total, how many ATP (NCERT count)?', '12', ['15', '10', '24'], '3 NADH (9) + 1 FADH<sub>2</sub> (2) + 1 GTP (1) = 12.');
mc(4, 'glycolysis', 'Which molecule is formed in glycolysis in 2 copies for each glucose?', 'BPGA', ['Fructose 1,6-bisphosphate', 'Glucose 6-phosphate', 'Fructose 6-phosphate'], 'The 6-carbon compounds are single. After the split, each 3-carbon compound is made in two copies.');
mc(4, 'glycolysis', 'Net ATP and NADH formed from one fructose 1,6-bisphosphate (the stage after both ATP investments) are', '4 ATP and 2 NADH', ['2 ATP and 2 NADH', '4 ATP and 4 NADH', '2 ATP and 4 NADH'], 'After the ATP investment, the splitting gives two 3-carbon units, each giving 2 ATP and 1 NADH.');
mc(4, 'glycolysis', 'The step that is the “energy investment” phase of glycolysis ends with', 'formation of fructose 1,6-bisphosphate', ['formation of pyruvic acid', 'formation of 3-PGA', 'formation of NADH'], 'Two ATP are used before the 6-carbon sugar is split.');
mc(4, 'fermentation', 'The NADH made in glycolysis under anaerobic conditions in yeast is finally used to', 'reduce acetaldehyde to ethanol', ['reduce O<sub>2</sub> to water', 'make ATP in the matrix', 'reduce CO<sub>2</sub> to glucose'], 'NAD<sup>+</sup> is thus regenerated for glycolysis.');
mc(4, 'fermentation', 'How many moles of ethanol and CO<sub>2</sub> are formed from two moles of glucose in fermentation?', '4 ethanol and 4 CO<sub>2</sub>', ['2 ethanol and 2 CO<sub>2</sub>', '4 ethanol and 2 CO<sub>2</sub>', '2 ethanol and 4 CO<sub>2</sub>'], 'One glucose gives 2 ethanol and 2 CO<sub>2</sub>.');
mc(4, 'Krebs cycle', 'Which of these is the 4-carbon compound formed by decarboxylation of the 5-carbon α-ketoglutarate and linked to CoA?', 'Succinyl CoA', ['Succinic acid', 'Fumaric acid', 'Oxaloacetic acid'], 'The reaction also gives NADH and CO<sub>2</sub>. Succinyl CoA then gives succinate and GTP.');
mc(4, 'Krebs cycle', 'If the enzyme that changes malic acid to OAA were inhibited, the cycle would', 'stop, since OAA could not combine with acetyl CoA', ['go faster', 'run with pyruvic acid instead', 'release more CO<sub>2</sub>'], 'The acceptor is not regenerated.');
mc(4, 'Krebs cycle', 'How many carbon atoms leave as CO<sub>2</sub> for each acetyl CoA that enters the cycle, and how many carbons are there in acetyl CoA?', '2 carbons leave; acetyl CoA has 2 carbons', ['1 carbon leaves; acetyl CoA has 2', '2 carbons leave; acetyl CoA has 3', '3 carbons leave; acetyl CoA has 3'], 'Two CO<sub>2</sub> are lost per turn, equal to the carbons added, though not the same atoms.');
mc(4, 'link reaction', 'A mitochondrion has no pyruvate dehydrogenase. Which will be seen?', 'Pyruvic acid piles up and Krebs cycle runs short of acetyl CoA', ['More ATP in glycolysis', 'Oxygen use rises', 'Fats cannot be used'], 'The link between glycolysis and the cycle is cut.');
mc(4, 'ETS', 'Cyanide blocks cytochrome c oxidase. Which will happen?', 'The ETS stops and the NADH level rises, so the Krebs cycle also slows', ['More oxygen is used', 'FADH<sub>2</sub> is formed in larger amounts', 'The proton gradient rises'], 'The carriers stay reduced, so the NAD<sup>+</sup> and FAD supply falls.');
mc(4, 'ETS', 'Which of these is true about the passage of electrons from FADH<sub>2</sub> compared with NADH?', 'FADH<sub>2</sub> electrons skip complex I, so fewer protons are pumped and less ATP is made', ['FADH<sub>2</sub> electrons enter at complex IV', 'FADH<sub>2</sub> gives more ATP than NADH', 'FADH<sub>2</sub> gives electrons to NAD<sup>+</sup>'], 'FADH<sub>2</sub> gives electrons through complex II, which does not pump protons, so the yield is 2 ATP.');
mc(4, 'ETS', 'In the ETS, the sequence of carriers for electrons from NADH is', 'complex I → ubiquinone → complex III → cyt c → complex IV → O<sub>2</sub>', ['complex I → cyt c → ubiquinone → complex IV → O<sub>2</sub>', 'complex II → complex I → complex III → O<sub>2</sub>', 'ubiquinone → complex IV → complex III → cyt c'], 'That is the standard order.');
mc(4, 'ETS', 'Which compartment of the mitochondrion has the highest H<sup>+</sup> concentration when the ETS runs?', 'The intermembrane (perimitochondrial) space', ['The matrix', 'The cytoplasm only', 'The inside of the cristae only'], 'Complexes I, III and IV pump protons out of the matrix into the intermembrane space.');
mc(4, 'RQ', 'In a tissue the RQ is 0.9. Which substrate is likely?', 'Protein', ['Carbohydrate', 'Organic acid', 'Pure fat'], 'RQ of about 0.9 is a figure for proteins, between fat and carbohydrate.');
mc(4, 'RQ', 'A leaf shows RQ near 1.3 in the dark. A likely reason is', 'organic acids being used as substrate', ['starch being used as substrate', 'fat being used as substrate', 'photosynthesis'], 'Organic acids give an RQ above one.');
mc(4, 'RQ', 'The equation for the oxidation of palmitic acid is C<sub>16</sub>H<sub>32</sub>O<sub>2</sub> + 23O<sub>2</sub> → 16CO<sub>2</sub> + 16H<sub>2</sub>O. Its RQ is about', '0.70', ['0.96', '1.0', '1.44'], 'RQ = 16 ÷ 23 = 0.696 ≈ 0.7.');
mc(4, 'RQ', 'Tartaric acid, C<sub>4</sub>H<sub>6</sub>O<sub>6</sub>, is oxidised: 2C<sub>4</sub>H<sub>6</sub>O<sub>6</sub> + 5O<sub>2</sub> → 8CO<sub>2</sub> + 6H<sub>2</sub>O. The RQ is', '1.6', ['0.63', '1.0', '1.33'], 'RQ = 8 ÷ 5 = 1.6.', 'Do not use 4 ÷ 5.');
mc(4, 'RQ', 'RQ of a mixture of equal volumes of O<sub>2</sub> used for carbohydrate (RQ 1) and fat (RQ 0.7) is', '0.85', ['0.7', '1.0', '1.7'], 'If 1 volume of O<sub>2</sub> is used on each, CO<sub>2</sub> = 1 + 0.7 = 1.7 for 2 volumes of O<sub>2</sub>. RQ = 0.85.', 'Weight by O<sub>2</sub> used, not by CO<sub>2</sub>.');
mc(4, 'amphibolic', 'Which pair of an intermediate and its fate is correct?', 'α-Ketoglutarate to glutamate by transamination', ['Succinate to fatty acid', 'Pyruvate to nucleic acid directly', 'Citrate to glucose by glycolysis'], 'Keto acids can be aminated to amino acids. The other pairs are not routes.');
mc(4, 'amphibolic', 'When a plant is starved of carbohydrate, it may use fat. The fat enters the pathway', 'mainly as acetyl CoA from fatty acid oxidation', ['as glucose', 'as pyruvic acid', 'as CO<sub>2</sub>'], 'Fatty acids give acetyl CoA, and glycerol gives PGAL.');
mc(4, 'mixed', 'In which part of a plant cell does ATP synthase function in both ATP making processes (aerobic respiration and photosynthesis)?', 'In the inner mitochondrial membrane and the thylakoid membrane', ['In the cytoplasm and the stroma', 'In the outer membrane of both', 'In the matrix and the lumen'], 'The membranes keep the proton gradient needed.');
mc(4, 'mixed', 'In a plant cell, which pair of molecules is made in photosynthesis and used in respiration?', 'Glucose and O<sub>2</sub>', ['NADPH and ATP of the thylakoid', 'CO<sub>2</sub> and water', 'RuBP and PEP'], 'Glucose is the substrate for respiration and O<sub>2</sub> is the terminal acceptor.');
mc(4, 'mixed', 'Compared with the chloroplast, the mitochondrial ETS differs because', 'the electron donor is NADH or FADH<sub>2</sub> and the final acceptor is O<sub>2</sub>', ['the donor is water and the acceptor is NADP<sup>+</sup>', 'it uses light', 'it releases O<sub>2</sub>'], 'In the chloroplast, water is the donor and NADP<sup>+</sup> is the final acceptor.');
stm(4, 'ETS', 'ATP synthase is called complex V.', 'F<sub>1</sub> is the proton channel and F<sub>0</sub> is the headpiece where ATP is made.', 2, 'F<sub>0</sub> is the channel and F<sub>1</sub> is the headpiece.');
stm(4, 'Krebs cycle', 'Succinate dehydrogenase is bound to the inner mitochondrial membrane.', 'The remaining Krebs cycle enzymes are in the matrix.', 0, 'Both are correct. This enzyme is also complex II of the ETS.');
stm(4, 'fermentation', 'In yeast fermentation, 2 ATP are made by oxidative phosphorylation.', 'Fermentation needs no oxygen.', 3, 'ATP in fermentation is made by substrate-level phosphorylation in glycolysis. So I is wrong.');
stm(4, 'RQ', 'In a respirometer with KOH, the change in volume shows the oxygen used.', 'Without KOH, the volume change shows the difference between CO<sub>2</sub> released and O<sub>2</sub> used.', 0, 'KOH absorbs CO<sub>2</sub>, so the fall in volume is the O<sub>2</sub> used. Without it, the change is the difference. Both are correct.');
asr(4, 'ETS', 'Passage of electrons from complex II is less able to build the proton gradient than from complex I.', 'Complex II does not pump protons.', 0, 'It is the reason FADH<sub>2</sub> yields less ATP.');
asr(5, 'RQ', 'A fully anaerobic tissue has an RQ of infinity.', 'It releases CO<sub>2</sub> and takes up no oxygen.', 0, 'Dividing by zero gives an unbounded ratio. R explains A.');
asr(4, 'Krebs cycle', 'The Krebs cycle releases two CO<sub>2</sub> per turn.', 'Both decarboxylations occur in the conversion of pyruvic acid to acetyl CoA.', 2, 'The decarboxylations are at isocitrate and α-ketoglutarate. Pyruvic acid conversion is the link reaction.');

// ---------------------------------------------------------------- Level 5
mc(5, 'ATP accounting', 'A yeast cell oxidises 5 glucose molecules aerobically (NCERT counts). The ATP made by substrate-level phosphorylation and by oxidative phosphorylation are', '20 and 170', ['10 and 180', '20 and 150', '38 and 152'], 'Substrate-level: 4 per glucose = 20. Oxidative: 34 per glucose = 170. Total 190 = 5 × 38.');
mc(5, 'ATP accounting', 'Which statement is NOT correct about the 38 ATP count?', 'It is the value measured exactly in every cell', ['It treats the glycolytic NADH as giving 3 ATP', 'It uses 3 ATP per NADH and 2 per FADH<sub>2</sub>', 'It is a theoretical, ideal value'], 'NCERT says it is a theoretical exercise. Real yields differ, as NADH from the cytoplasm needs transport and some protons leak.');
mc(5, 'ATP accounting', 'A pyruvic acid labelled at its carbonyl carbon (C-2) is taken through the link reaction and the Krebs cycle. Which is true?', 'The label appears as CO<sub>2</sub> only in later turns, since the first CO<sub>2</sub> comes from the carboxyl carbon', ['The label is lost as CO<sub>2</sub> in the link reaction', 'The label is lost as CO<sub>2</sub> in glycolysis', 'The label can never be released as CO<sub>2</sub>'], 'The link reaction removes the carboxyl carbon (C-1). The carbonyl carbon is in acetyl CoA and is lost in a later turn of the cycle.');
mc(5, 'ATP accounting', 'For one mole of glucose oxidised aerobically, which pair of statements about O<sub>2</sub> and CO<sub>2</sub> is correct?', '6 O<sub>2</sub> and 6 CO<sub>2</sub>; each O<sub>2</sub> accepts 4 electrons', ['6 O<sub>2</sub> and 12 CO<sub>2</sub>; each O<sub>2</sub> accepts 2 electrons', '12 O<sub>2</sub> and 6 CO<sub>2</sub>; each O<sub>2</sub> accepts 4 electrons', '3 O<sub>2</sub> and 6 CO<sub>2</sub>; each O<sub>2</sub> accepts 8 electrons'], 'C<sub>6</sub>H<sub>12</sub>O<sub>6</sub> + 6O<sub>2</sub> → 6CO<sub>2</sub> + 6H<sub>2</sub>O. O<sub>2</sub> + 4e<sup>−</sup> + 4H<sup>+</sup> → 2H<sub>2</sub>O. So 24 electrons for 6 O<sub>2</sub>, from 10 NADH and 2 FADH<sub>2</sub> (24 electrons).');
mc(5, 'glycolysis', 'In which step of glycolysis does NAD<sup>+</sup> act as an oxidising agent AND an inorganic phosphate is added?', 'PGAL to 1,3-bisphosphoglycerate (BPGA)', ['BPGA to 3-PGA', '2-PGA to PEP', 'DHAP to PGAL'], 'This single step oxidises and phosphorylates, giving NADH.');
mc(5, 'glycolysis', 'Glycolysis of sucrose rather than glucose differs in that', 'the sucrose is first split to glucose and fructose, and each is phosphorylated', ['it gives four pyruvic acids from one sucrose', 'no ATP is needed', 'it occurs in the matrix'], 'Sucrose has two hexose units, so two hexoses go through glycolysis, giving 4 pyruvic acids from one sucrose.', 'Four pyruvic acids are formed, but the splitting is the point of difference.');
mc(5, 'fermentation', 'Which is a correct statement about fermentation?', 'ATP is made only by substrate-level phosphorylation', ['ATP is made by oxidative phosphorylation', 'Glucose is fully oxidised to CO<sub>2</sub> and H<sub>2</sub>O', 'NADH is used to make ATP'], 'Fermentation yields 2 ATP from glycolysis. NADH is used only to reduce the product.');
mc(5, 'Krebs cycle', 'A scientist feeds <sup>14</sup>C-labelled acetyl CoA (both carbons labelled) to a mitochondrial preparation. After one turn of the cycle, the carbon atoms released as CO<sub>2</sub> are', 'not the ones from the acetyl CoA, but from OAA', ['those of acetyl CoA, both', 'one from acetyl CoA and one from OAA', 'none; CO<sub>2</sub> is released in the link reaction'], 'In the first turn, the two CO<sub>2</sub> carbons come from the carbons of the OAA part. The acetyl carbons are lost in later turns.', 'This is a classic top-rank detail.');
mc(5, 'ETS', 'A substance blocks F<sub>0</sub> of ATP synthase but not the electron carriers. Which is expected?', 'The proton gradient rises, electron flow slows, and ATP production stops', ['Electron flow speeds up', 'Protons leak faster to the matrix', 'ATP production rises'], 'With no flow of protons through F<sub>0</sub>, the gradient builds up, which holds back the pumps.');
mc(5, 'ETS', 'DNP is an uncoupler. It carries protons across the inner membrane. Which result is seen?', 'Heat is released, oxygen use rises, and ATP synthesis falls', ['ATP synthesis rises', 'Oxygen use falls', 'The gradient is increased'], 'Energy of electron flow is lost as heat, with no ATP made.');
mc(5, 'RQ', 'A seed has 60 per cent of its O<sub>2</sub> used on carbohydrate (RQ 1) and 40 per cent on fat (RQ 0.7). Its overall RQ is', '0.88', ['0.85', '0.7', '1.0'], 'CO<sub>2</sub> per unit O<sub>2</sub> = 0.6 × 1 + 0.4 × 0.7 = 0.88.');
mc(5, 'RQ', 'Which of these will give an RQ greater than 1?', 'Oxidation of oxalic acid: 2C<sub>2</sub>H<sub>2</sub>O<sub>4</sub> + O<sub>2</sub> → 4CO<sub>2</sub> + 2H<sub>2</sub>O', ['Oxidation of glucose', 'Oxidation of tripalmitin', 'Oxidation of sucrose'], 'The first gives RQ = 4. Glucose and sucrose give 1, and tripalmitin 0.7.');
mc(5, 'amphibolic', 'Which statement about an amphibolic pathway is the most accurate?', 'The same intermediates are used for degradation and for synthesis, with direction set by the cell’s needs', ['It runs only in the breakdown direction', 'It is found only in mitochondria and only in animals', 'It makes no ATP'], 'In respiration, intermediates are drawn out for biosynthesis and refilled from other sources.');
mc(5, 'amphibolic', 'A rapidly growing cell draws α-ketoglutarate and OAA out of the Krebs cycle for amino acid synthesis. For the cycle to continue, which is needed?', 'A supply of replacement intermediates, such as OAA from pyruvate', ['Removal of acetyl CoA', 'Stopping glycolysis', 'More NADH'], 'Anaplerotic reactions refill the cycle. If OAA is not refilled, acetyl CoA cannot enter.');
nat(2, 'ATP accounting', 'How many NADH are formed in glycolysis and the link reaction together from one glucose?', 4, '2 in glycolysis and 2 in the link reaction.');
nat(3, 'ATP accounting', 'How many ATP are made in total (NCERT count) from complete oxidation of 3 glucose molecules?', 114, '3 × 38 = 114.');
nat(3, 'ATP accounting', 'How many ATP are made by oxidative phosphorylation from the 6 NADH and 2 FADH<sub>2</sub> of the Krebs cycle (NCERT count) for one glucose?', 22, '6 × 3 = 18 and 2 × 2 = 4. Total 22.', 'The 2 ATP made by substrate-level phosphorylation are not included.');
nat(4, 'Krebs cycle', 'How many CO<sub>2</sub> are released when 5 molecules of pyruvic acid are completely oxidised?', 15, 'Each pyruvic acid gives 3 CO<sub>2</sub>: 1 in the link reaction, 2 in the cycle. 5 × 3 = 15.');
nat(4, 'ATP accounting', 'How many ATP are made from 4 acetyl CoA in the Krebs cycle and ETS (NCERT count)?', 48, 'Each acetyl CoA gives 12 ATP: 3 NADH (9) + FADH<sub>2</sub> (2) + GTP (1). 4 × 12 = 48.');
nat(5, 'RQ', 'Respiration of a certain substrate uses 25 mL of O<sub>2</sub> and releases 20 mL of CO<sub>2</sub>. If this is repeated for 5 identical tissues, what is the total volume of CO<sub>2</sub> released, in mL?', 100, 'CO<sub>2</sub> = 20 × 5 = 100 mL. (RQ = 0.8.)');

// ---------------------------------------------------------------- Expansion (added 2026-11-22; ids continue the numbering above)
function mx(level, sub, key, title, L1, L2, map, sol, trap) {
  const code = (m) => m.map((x, i) => `${'ABCD'[i]}-${x}`).join(', ');
  const sw = (i, j) => { const m = [...map]; [m[i], m[j]] = [m[j], m[i]]; return m; };
  const wr = [];
  for (const [i, j] of [[0, 1], [2, 3], [0, 3], [1, 2], [0, 2], [1, 3]]) { const c = code(sw(i, j)); if (c !== code(map) && !wr.includes(c)) wr.push(c); if (wr.length === 3) break; }
  groups[key] = { title, list1: L1.map((x, i) => `${'ABCD'[i]}. ${x}`), list2: L2.map((x, i) => `${'pqrst'[i]}. ${x}`) };
  const p = POS[pos++ % 4];
  const options = [...wr]; options.splice(p, 0, code(map));
  items.push({ id: nid(), type: 'mcq', level, format: 'match', exams: EXXX(level), sub, group: key, q: 'Match List I with List II and choose the correct code.', options, answer: p, sol, ...(trap ? { trap } : {}) });
}
function ct(level, sub, stmts, trap, lead = 'How many of the following statements are correct?') {
  const R = ['(i)', '(ii)', '(iii)', '(iv)'];
  const k = stmts.filter((s) => s[1]).length;
  if (stmts.length !== 4 || k < 1) throw new Error('ct needs 4 statements and at least one correct');
  const q = `${lead}<br>` + stmts.map((s, i) => `${R[i]} ${s[0]}`).join('<br>');
  const sol = stmts.map((s, i) => `${R[i]} ${s[1] ? 'Correct' : 'Incorrect'}. ${s[2]}`).join('<br>') + `<br>So ${k === 1 ? 'only one statement is' : k === 4 ? 'all four statements are' : (k === 2 ? 'two' : 'three') + ' statements are'} correct.`;
  items.push({ id: nid(), type: 'mcq', level, format: 'statements', exams: EXXX(level), sub, q, options: ['Only one', 'Only two', 'Only three', 'All four'], answer: k - 1, sol, ...(trap ? { trap } : {}) });
}
function nt(level, sub, q, answer, sol, trap) {
  items.push({ id: nid(), type: 'nat', level, format: 'integer', exams: EXXX(level), sub, q, answer, tol: 0, sol, ...(trap ? { trap } : {}) });
}
const EXXX = ()=>E;
// ---- Level 2
mc(2, 'glycolysis', 'The word "glycolysis" comes from the Greek words', 'glycos (sugar) and lysis (splitting)', ['glucose and synthesis', 'glycos (sugar) and oxidation', 'gas and lysis (burning)'], 'Glycolysis means the splitting of sugar. Glucose (6C) is split into two pyruvic acid (3C) molecules.');
mc(2, 'glycolysis', 'In glycolysis, the 3-carbon sugar phosphate that is interconverted with dihydroxyacetone phosphate (DHAP) is', 'phosphoglyceraldehyde (PGAL)', ['bisphosphoglyceric acid (BPGA)', 'phosphoenolpyruvate (PEP)', '3-phosphoglyceric acid (3-PGA)'], 'Fructose 1,6-bisphosphate splits into DHAP and PGAL, and the two are readily interconverted. Only PGAL goes on to the next step, so both halves of the sugar are used.');
mc(2, 'mitochondrion', 'The inward folds of the inner mitochondrial membrane are called', 'cristae', ['grana', 'thylakoids', 'microvilli'], 'The cristae increase the surface area of the inner membrane, which carries the ETS and ATP synthase.');
mc(2, 'mitochondrion', 'Which one is present in the mitochondrial matrix?', 'a single circular DNA, a few RNA molecules and ribosomes', ['many linear chromosomes with histones', 'only enzymes and no nucleic acid', 'chlorophyll and ribulose bisphosphate carboxylase'], 'The matrix holds the Krebs cycle enzymes and also a single circular DNA, a few RNA molecules, ribosomes and the components for its own protein synthesis.');
mc(2, 'mitochondrion', 'The outer membrane of a mitochondrion is', 'freely permeable to small molecules', ['impermeable to all ions', 'folded into cristae', 'the site of ATP synthase'], 'The outer membrane is freely permeable to small molecules. The inner membrane is selective, folded into cristae and holds the ETS and ATP synthase.');
mc(2, 'Krebs cycle', 'The Krebs cycle is also known as the TCA cycle because', 'its first product, citric acid, has three carboxyl groups', ['it has three turns for each glucose', 'it makes three ATP in each turn', 'it needs three coenzymes only'], 'TCA stands for tricarboxylic acid. Citric acid has three –COOH groups.');
mc(2, 'ATP accounting', 'The number of ATP (or GTP) made by substrate-level phosphorylation in the Krebs cycle for one glucose is', '2', ['1', '4', '6'], 'One GTP (changed to ATP) is made per turn at succinyl CoA to succinic acid. One glucose gives two acetyl CoA, so two turns and two ATP.');
mc(2, 'fermentation', 'The change of milk to curd by bacteria is an example of', 'lactic acid fermentation', ['alcoholic fermentation', 'aerobic respiration', 'photophosphorylation'], 'Lactic acid bacteria change lactose in milk to lactic acid. This is a fermentation.');
mc(2, 'link reaction', 'The compound that moves from the cytoplasm into the mitochondrion for the link reaction is', 'pyruvic acid', ['glucose', 'PGAL', 'acetyl CoA'], 'Pyruvic acid made in glycolysis crosses into the matrix, where it is changed to acetyl CoA. Glucose never enters the mitochondrion.');
mc(2, 'ETS', 'In the ETS, the final product formed when electrons are passed to oxygen is', 'water', ['carbon dioxide', 'hydrogen peroxide', 'NADH'], 'Oxygen takes electrons and protons to form H<sub>2</sub>O at complex IV.');
mc(2, 'basics', 'Gas exchange in the stem of a woody tree takes place mainly through', 'lenticels', ['hydathodes', 'root hairs', 'guard cells of the bark'], 'Woody stems have lenticels for gas exchange. Leaves use stomata.');
mc(2, 'RQ', 'In a respirometer, the substance that absorbs CO<sub>2</sub> so that O<sub>2</sub> use alone can be measured is', 'potassium hydroxide (KOH)', ['calcium chloride', 'sodium chloride', 'sucrose'], 'KOH takes up the CO<sub>2</sub>, so the fall in gas volume equals the O<sub>2</sub> used.');
// ---- Level 3
mc(3, 'mitochondrion', 'Which is true for the inner mitochondrial membrane?', 'It is impermeable to most ions and carries the ETS and ATP synthase', ['It is freely permeable to protons', 'It has no proteins', 'It forms the intermembrane space only on its inside'], 'The inner membrane is a tight barrier. This is why a proton gradient can build up across it.', 'The outer membrane is the leaky one.');
mc(3, 'glycolysis', 'In glycolysis, the conversion of glucose to glucose 6-phosphate and of fructose 6-phosphate to fructose 1,6-bisphosphate each', 'uses one ATP', ['makes one ATP', 'makes one NADH', 'releases one CO<sub>2</sub>'], 'Both are phosphorylations that spend ATP. They set up the sugar to be split.');
mc(3, 'glycolysis', 'How many carbon atoms does each of the two molecules made by splitting fructose 1,6-bisphosphate have?', 'three', ['two', 'four', 'six'], 'The 6C sugar bisphosphate splits into DHAP and PGAL, both with three carbons.');
mc(3, 'glycolysis', 'The total number of phosphate groups that must be added to one glucose before it splits in glycolysis is', 'two', ['one', 'three', 'four'], 'One goes onto C-6 (glucose 6-phosphate) and one onto C-1 (fructose 1,6-bisphosphate).', 'BPGA, made later, gets a phosphate too, but that is after the split.');
mc(3, 'glycolysis', 'How many molecules of ATP are made by substrate-level phosphorylation from one molecule of PGAL passing through to pyruvic acid?', '2', ['1', '4', '0'], 'BPGA to 3-PGA gives one ATP and PEP to pyruvic acid gives one. So 2 ATP per PGAL, 4 per glucose.');
mc(3, 'fermentation', 'Of the energy in glucose, the fraction released in fermentation is less than', '7 per cent', ['25 per cent', '40 per cent', '70 per cent'], 'Less than 7 per cent of the energy in glucose is released in fermentation, and only part of it is trapped as ATP.', 'Do not confuse with the roughly 40 per cent efficiency of aerobic respiration.');
mc(3, 'fermentation', 'In which of these is NAD<sup>+</sup> regenerated without a mitochondrion?', 'conversion of acetaldehyde to ethanol in yeast', ['conversion of succinic acid to fumaric acid', 'conversion of malic acid to OAA', 'oxidation of NADH at complex I'], 'Acetaldehyde accepts electrons from NADH and becomes ethanol, which gives back NAD<sup>+</sup>. The other three are mitochondrial; malic acid to OAA actually makes NADH.');
mc(3, 'fermentation', 'Two pyruvic acid molecules change to lactic acid in a muscle cell. Which pair of statements is correct?', 'NADH is oxidised and no CO<sub>2</sub> is released', ['NADH is made and CO<sub>2</sub> is released', 'NADH is oxidised and CO<sub>2</sub> is released', 'FADH<sub>2</sub> is oxidised and no CO<sub>2</sub> is released'], 'Pyruvic acid + NADH → lactic acid + NAD<sup>+</sup>. There is no decarboxylation, so no CO<sub>2</sub>.', 'Alcoholic fermentation does release CO<sub>2</sub>; lactic does not.');
mc(3, 'link reaction', 'Which is NOT a product of the link reaction for one pyruvic acid?', 'FADH<sub>2</sub>', ['acetyl CoA', 'CO<sub>2</sub>', 'NADH + H<sup>+</sup>'], 'Pyruvic acid + CoA + NAD<sup>+</sup> → acetyl CoA + CO<sub>2</sub> + NADH + H<sup>+</sup>. FADH<sub>2</sub> is not made here.');
mc(3, 'link reaction', 'The enzyme complex of the link reaction needs which ion as a cofactor?', 'Mg<sup>2+</sup>', ['Ca<sup>2+</sup>', 'Fe<sup>3+</sup>', 'Zn<sup>2+</sup>'], 'The pyruvate dehydrogenase step uses NAD<sup>+</sup>, coenzyme A and Mg<sup>2+</sup>.');
mc(3, 'Krebs cycle', 'During the conversion of succinyl CoA to succinic acid in the Krebs cycle, the nucleotide that is first phosphorylated is', 'GDP, giving GTP', ['ADP only, giving ATP', 'AMP, giving ADP', 'FAD, giving FADH<sub>2</sub>'], 'GDP + Pi → GTP, and GTP passes its phosphate to ADP to give ATP. The plant text names it substrate-level phosphorylation.');
mc(3, 'Krebs cycle', 'Which step of the Krebs cycle needs the addition of water?', 'fumaric acid to malic acid', ['succinic acid to fumaric acid', 'malic acid to OAA', 'α-ketoglutaric acid to succinyl CoA'], 'Fumarate + H<sub>2</sub>O → malate. Condensation of acetyl CoA with OAA also uses water, to release CoA and give citric acid.', 'Citric acid formation also takes water, but it is not in the options.');
mc(3, 'Krebs cycle', 'The Krebs cycle begins with the condensation of acetyl CoA (2C) with', 'oxaloacetic acid (4C), giving citric acid (6C)', ['citric acid (6C), giving isocitric acid (6C)', 'pyruvic acid (3C), giving a 5C compound', 'succinic acid (4C), giving malic acid (4C)'], 'OAA (4C) + acetyl CoA (2C) + H<sub>2</sub>O → citric acid (6C) + CoA.');
mc(3, 'ETS', 'For every ATP made by ATP synthase, the number of protons that pass through the F<sub>0</sub> channel (NCERT) is', '2', ['1', '3', '4'], 'NCERT states that for each ATP produced, 2H<sup>+</sup> pass through the F<sub>0</sub> channel.', 'The commonly quoted 3–4 H<sup>+</sup> per ATP is not the NCERT value.');
mc(3, 'ETS', 'The ETS component that is NOT a protein complex but a small mobile lipid-soluble carrier is', 'ubiquinone', ['cytochrome c oxidase', 'NADH dehydrogenase', 'succinate dehydrogenase'], 'Ubiquinone (coenzyme Q) moves in the membrane. Cytochrome c is mobile too, but it is a small protein.');
mc(3, 'ETS', 'Electrons pass from complex III to complex IV by way of', 'cytochrome c', ['ubiquinone', 'FAD', 'NAD<sup>+</sup>'], 'Complex III hands electrons to cytochrome c, a small protein on the outer face of the inner membrane, and cytochrome c hands them to complex IV. Ubiquinone sits between complexes I/II and III.');
mc(3, 'ETS', 'Which statement is correct about oxidative phosphorylation in plants?', 'ATP is made using energy released when electrons move down the ETS', ['ATP is made directly by the transfer of phosphate from PEP', 'ATP is made by the splitting of water', 'ATP is made only in the cytoplasm'], 'Energy from electron flow pumps protons, and the gradient drives ATP synthase. PEP to pyruvic acid is substrate-level phosphorylation.');
mc(3, 'RQ', 'The RQ of stearic acid, C<sub>18</sub>H<sub>36</sub>O<sub>2</sub> + 26O<sub>2</sub> → 18CO<sub>2</sub> + 18H<sub>2</sub>O, is about', '0.69', ['1.44', '0.9', '1.0'], 'RQ = 18 ÷ 26 = 0.69. Like all fatty acids, it is low in oxygen, so it needs a lot of O<sub>2</sub>.');
mc(3, 'RQ', 'Malic acid is oxidised: C<sub>4</sub>H<sub>6</sub>O<sub>5</sub> + 3O<sub>2</sub> → 4CO<sub>2</sub> + 3H<sub>2</sub>O. Its RQ is', '1.33', ['0.75', '1.0', '0.33'], 'RQ = 4 ÷ 3 = 1.33. Organic acids have more oxygen per carbon than sugar, so they need less O<sub>2</sub>.');
mc(3, 'RQ', 'In a respirometer without KOH, a germinating seed that is using only carbohydrate shows', 'no change in gas volume, because CO<sub>2</sub> released equals O<sub>2</sub> used', ['a fall in volume', 'a rise in volume', 'a sudden fall then a rise'], 'For glucose, 6 O<sub>2</sub> are used and 6 CO<sub>2</sub> are released, so the total gas volume is unchanged.', 'A student may forget that no KOH means no CO<sub>2</sub> absorption.');
mc(3, 'RQ', 'When fat is the substrate and no KOH is used, the gas volume in a closed respirometer', 'falls, since CO<sub>2</sub> released is less than O<sub>2</sub> used', ['rises', 'stays the same', 'falls to zero'], 'RQ below one means less CO<sub>2</sub> comes out than O<sub>2</sub> goes in, so the net volume decreases.');
mc(3, 'amphibolic', 'Which pair is correct?', 'Fatty acids → acetyl CoA; glycerol → PGAL', ['Fatty acids → PGAL; glycerol → acetyl CoA', 'Fatty acids → pyruvic acid; glycerol → OAA', 'Fatty acids → OAA; glycerol → succinyl CoA'], 'Fatty acids are broken to acetyl CoA. Glycerol is converted to PGAL, which joins glycolysis.', 'The two are often swapped.');
mc(3, 'amphibolic', 'The anabolic pathway that draws acetyl CoA out of the respiratory pathway is the synthesis of', 'fatty acids', ['glucose from CO<sub>2</sub>', 'DNA bases only', 'chlorophyll'], 'Acetyl CoA is the building block for fatty acids, so fat synthesis draws on it.');
mc(3, 'ATP accounting', 'Which of these makes ATP both by substrate-level and by oxidative phosphorylation?', 'complete oxidation of glucose to CO<sub>2</sub> and H<sub>2</sub>O', ['alcoholic fermentation of glucose', 'lactic acid fermentation of glucose', 'conversion of acetaldehyde to ethanol'], 'Aerobic oxidation makes ATP by substrate-level steps (glycolysis, Krebs cycle) and by oxidative phosphorylation in the ETS. The fermentations make ATP only in glycolysis.');
mc(3, 'mixed', 'A common feature of respiration and photosynthesis is that both', 'use an electron transport chain and ATP synthase in a membrane', ['occur in the mitochondrion', 'need light', 'use water as the final electron acceptor'], 'Both use electron flow to build a proton gradient, which drives ATP synthase. Mitochondria use the inner membrane, chloroplasts the thylakoid.');

// ---- Match the lists
mx(2, 'enzymes', 'prx1', 'Enzyme and its reaction', ['Hexokinase', 'Pyruvate dehydrogenase', 'Alcohol dehydrogenase', 'ATP synthase'], ['Acetaldehyde to ethanol', 'Glucose to glucose 6-phosphate', 'Pyruvic acid to acetyl CoA', 'ADP + Pi to ATP using proton flow'], ['q', 'r', 'p', 's'], 'Hexokinase phosphorylates glucose. Pyruvate dehydrogenase makes acetyl CoA in the link reaction. Alcohol dehydrogenase reduces acetaldehyde to ethanol. ATP synthase makes ATP.');
mx(3, 'mitochondrion', 'prx2', 'Compartment and event', ['Cytoplasm', 'Mitochondrial matrix', 'Inner mitochondrial membrane', 'Intermembrane space'], ['Glycolysis', 'Link reaction and Krebs cycle', 'ETS and ATP synthase', 'Protons build up when the ETS runs'], ['p', 'q', 'r', 's'], 'Glycolysis is in the cytoplasm. The matrix has the link reaction and Krebs cycle enzymes. The inner membrane carries the ETS. Protons are pumped into the intermembrane space.');
mx(3, 'Krebs cycle', 'prx3', 'Krebs cycle compound and feature', ['Oxaloacetic acid', 'Citric acid', 'α-Ketoglutaric acid', 'Succinic acid'], ['Five-carbon acid', 'Reduced FAD is made when it is oxidised', 'Regenerated at the end of the cycle', 'First product of the cycle, six carbons'], ['r', 's', 'p', 'q'], 'OAA is regenerated. Citric acid (6C) is the first product. α-Ketoglutaric acid has 5C. Succinic acid is oxidised to fumaric acid with FAD.', 'Check the carbon number as well as the position in the cycle.');
mx(3, 'RQ', 'prx4', 'Substrate and RQ', ['Glucose', 'Stearic acid', 'Malic acid', 'Oxalic acid'], ['4', '1', '0.69', '1.33'], ['q', 'r', 's', 'p'], 'Glucose: 6 CO<sub>2</sub> / 6 O<sub>2</sub> = 1. Stearic acid: 18/26 = 0.69. Malic acid: 4/3 = 1.33. Oxalic acid: 2C<sub>2</sub>H<sub>2</sub>O<sub>4</sub> + O<sub>2</sub> → 4CO<sub>2</sub> + 2H<sub>2</sub>O, so 4/1 = 4.');
mx(4, 'fermentation', 'prx5', 'Condition and outcome', ['Yeast glycolysis with no O<sub>2</sub>', 'Muscle glycolysis in heavy exercise', 'Link reaction', 'Succinyl CoA to succinic acid'], ['Ends with lactic acid and no CO<sub>2</sub>', 'ATP made by substrate-level phosphorylation', 'Pyruvic acid loses CO<sub>2</sub> and NAD<sup>+</sup> is reduced', 'Ends with ethanol and CO<sub>2</sub>'], ['s', 'p', 'r', 'q'], 'Yeast ferments to ethanol and CO<sub>2</sub>. Muscle makes lactic acid with no CO<sub>2</sub>. The link reaction releases CO<sub>2</sub> and reduces NAD<sup>+</sup>. The conversion of succinyl CoA to succinic acid gives GTP, then ATP.');
mx(4, 'ATP accounting', 'prx6', 'Count per glucose (NCERT)', ['NADH from glycolysis and the link reaction together', 'NADH from the Krebs cycle', 'FADH<sub>2</sub> in total', 'NADH in total'], ['2', '4', '6', '10'], ['q', 'r', 'p', 's'], 'Glycolysis 2 + link reaction 2 = 4. Krebs cycle 3 per turn × 2 = 6. FADH<sub>2</sub>: 1 per turn × 2 = 2. Total NADH = 2 + 2 + 6 = 10.');
mx(4, 'amphibolic', 'prx7', 'Substrate and entry into respiration', ['Fatty acids', 'Glycerol', 'Amino acids after deamination', 'Sucrose'], ['Acetyl CoA', 'PGAL', 'Pyruvic acid or Krebs cycle intermediates', 'Split to glucose and fructose by invertase first'], ['p', 'q', 'r', 's'], 'Fatty acids give acetyl CoA, glycerol gives PGAL, amino acids enter at pyruvic acid, acetyl CoA or a Krebs cycle acid, and sucrose is split by invertase before glycolysis.');
mx(4, 'ETS', 'prx8', 'Complex and feature', ['NADH dehydrogenase', 'Succinate dehydrogenase', 'Cytochrome c oxidase', 'ATP synthase'], ['First complex; receives electrons from NADH', 'Also a Krebs cycle enzyme', 'Has copper centres and reduces O<sub>2</sub>', 'Has F<sub>1</sub> and F<sub>0</sub> parts'], ['p', 'q', 'r', 's'], 'Complex I takes electrons from NADH. Complex II is succinate dehydrogenase, which is also in the Krebs cycle. Complex IV has Cu centres and reduces O<sub>2</sub>. Complex V is F<sub>1</sub>F<sub>0</sub>.');
mx(4, 'mixed', 'prx9', 'Mitochondria and chloroplast comparison', ['ATP synthase of a mitochondrion', 'ATP synthase of a chloroplast', 'NADH', 'NADPH'], ['Made in the light reaction', 'F<sub>0</sub>–F<sub>1</sub>', 'Made in glycolysis', 'CF<sub>0</sub>–CF<sub>1</sub>'], ['q', 's', 'r', 'p'], 'Mitochondrial ATP synthase is F<sub>0</sub>–F<sub>1</sub>, the chloroplast one is CF<sub>0</sub>–CF<sub>1</sub>. NADH is made in glycolysis (and elsewhere in respiration). NADPH is made in the light reaction.', 'NADH goes with respiration and NADPH with photosynthesis.');
mx(4, 'RQ', 'prx10', 'Tissue and RQ', ['Germinating wheat grain (starch)', 'Germinating castor seed (fat)', 'Leaf using organic acids', 'Yeast with no O<sub>2</sub>'], ['About 0.7', 'About 1.0', 'Greater than 1', 'Infinity'], ['q', 'p', 'r', 's'], 'Starch gives 1, fat about 0.7, organic acids more than 1, and a purely anaerobic tissue releases CO<sub>2</sub> with no O<sub>2</sub> use, so RQ is infinite.');

// ---- Count the correct statements
ct(3, 'glycolysis', [['Glycolysis occurs in the cytoplasm of aerobic as well as anaerobic cells.', true, 'It is the common first step.'], ['The net gain of glycolysis is 2 ATP and 2 NADH per glucose.', true, 'Four ATP are made and two are used.'], ['CO<sub>2</sub> is released during glycolysis.', false, 'Glycolysis only splits the 6C sugar into two 3C acids. No carbon is lost.'], ['PGAL is oxidised by NAD<sup>+</sup> as it is changed to BPGA.', true, 'This is the step that makes NADH.']]);
ct(3, 'link reaction', [['The link reaction occurs in the cytoplasm.', false, 'It occurs in the mitochondrial matrix.'], ['It needs FAD as the electron acceptor.', false, 'NAD<sup>+</sup> is the acceptor.'], ['It makes ATP directly by substrate-level phosphorylation.', false, 'No ATP is made in it.'], ['Pyruvic acid loses one carbon as CO<sub>2</sub>.', true, 'Oxidative decarboxylation gives acetyl CoA (2C).']]);
ct(3, 'mitochondrion', [['The outer membrane of a mitochondrion is freely permeable to small molecules.', true, 'This is the case.'], ['The cristae are folds of the inner membrane.', true, 'They increase surface area.'], ['The matrix has ribosomes and a circular DNA.', true, 'It can make some of its own proteins.'], ['The Krebs cycle enzymes are found in the intermembrane space.', false, 'They are in the matrix (succinate dehydrogenase is in the inner membrane).']]);
ct(4, 'Krebs cycle', [['One turn of the cycle releases two CO<sub>2</sub>.', true, 'Both decarboxylations are in the cycle itself.'], ['FADH<sub>2</sub> is made when succinic acid changes to fumaric acid.', true, 'Succinate dehydrogenase uses FAD.'], ['Six FADH<sub>2</sub> are made in the cycle for one glucose.', false, 'One per turn and two turns give 2 FADH<sub>2</sub>.'], ['Citric acid is made when pyruvic acid combines directly with OAA.', false, 'Acetyl CoA, not pyruvic acid, combines with OAA.']]);
ct(4, 'ETS', [['Cytochrome c is a small mobile protein between complexes III and IV.', true, 'It carries electrons.'], ['Ubiquinone receives electrons from complexes I and II.', true, 'It carries them to complex III.'], ['Cytochrome c oxidase has cytochromes a and a<sub>3</sub> and two copper centres.', true, 'This is complex IV.'], ['Protons are pumped into the mitochondrial matrix.', false, 'They are pumped into the intermembrane space.']]);
ct(4, 'RQ', [['The RQ of fat is less than one.', true, 'Fat is poor in oxygen.'], ['The RQ of protein is about 0.9.', true, 'This is the NCERT value.'], ['The RQ of organic acids is less than one.', false, 'It is greater than one.'], ['The RQ of a fully anaerobic tissue is zero.', false, 'It is infinity, because no O<sub>2</sub> is used.']]);
ct(5, 'amphibolic', [['Acetyl CoA is drawn off for fatty acid synthesis.', true, 'Fat synthesis is anabolic.'], ['α-Ketoglutaric acid can be used to make the amino acid glutamic acid.', true, 'This needs an amino group (transamination).'], ['OAA can be used to make the amino acid aspartic acid.', true, 'This is also a transamination.'], ['In starvation, fats and proteins can also be respired.', true, 'They enter as acetyl CoA or as other intermediates.']], 'When the last one is also true, "all four" is the key.');

// ---- Statements I and II
stm(3, 'glycolysis', 'The conversion of PEP to pyruvic acid makes ATP by substrate-level phosphorylation.', 'This step takes place in the mitochondrial matrix.', 2, 'Statement I is correct. Statement II is wrong, because all of glycolysis, including this step, is in the cytoplasm.');
stm(4, 'mitochondrion', 'The inner mitochondrial membrane is freely permeable to ions.', 'The outer mitochondrial membrane is freely permeable to small molecules.', 3, 'Statement I is wrong: the inner membrane is a tight barrier, which lets a proton gradient build up. Statement II is correct.');
stm(4, 'ETS', 'Oxygen is the final acceptor of electrons in the ETS.', 'Water is formed at complex IV.', 0, 'Both are correct: complex IV passes electrons to O<sub>2</sub>, which combines with protons to make H<sub>2</sub>O.');
stm(5, 'RQ', 'The RQ of fat is greater than one.', 'The RQ of organic acids is less than one.', 1, 'Both are wrong: fat has an RQ of about 0.7 and organic acids have an RQ above one.');
stm(4, 'glycolysis', 'Glycolysis needs oxygen.', 'Glycolysis is the common first step of aerobic and anaerobic respiration.', 3, 'Statement I is wrong: glycolysis does not use oxygen. Statement II is correct.');
stm(5, 'ETS', 'Electrons from FADH<sub>2</sub> enter the ETS at complex II, so FADH<sub>2</sub> gives fewer ATP than NADH.', 'Succinate dehydrogenase is a Krebs cycle enzyme that is also complex II of the ETS.', 0, 'Both are correct. FADH<sub>2</sub> gives 2 ATP and NADH gives 3 (NCERT) as the electrons from FADH<sub>2</sub> bypass complex I. Succinate dehydrogenase is both a Krebs cycle enzyme and complex II.');

// ---- Assertion and reason
asr(3, 'fermentation', 'Fermentation can go on without oxygen.', 'NAD<sup>+</sup> is regenerated when the products of glycolysis are reduced to ethanol or lactic acid.', 0, 'Glycolysis needs NAD<sup>+</sup>. Reducing acetaldehyde or pyruvic acid gives it back, so glycolysis can continue without O<sub>2</sub>. R explains A.');
asr(4, 'mitochondrion', 'ATP synthesis in a mitochondrion needs an intact inner membrane.', 'A proton gradient is set up across the inner membrane.', 0, 'The gradient drives ATP synthase. A leaky membrane cannot hold it.');
asr(4, 'Krebs cycle', 'Two ATP (or GTP) are made in the Krebs cycle for each glucose.', 'One GTP is made in each turn of the cycle and one glucose gives two acetyl CoA.', 0, 'One substrate-level step per turn and two turns give 2.');
asr(4, 'fermentation', 'Roots of plants in waterlogged soil make much less ATP.', 'Fermentation yields much less ATP than aerobic respiration.', 0, 'With no O<sub>2</sub>, root cells ferment and get only 2 ATP per glucose against 38.');
asr(5, 'RQ', 'The RQ of a seed using both fat and carbohydrate lies between 0.7 and 1.', 'The RQ of a mixture is the weighted mean of the RQ of its parts, weighted by oxygen used.', 0, 'The CO<sub>2</sub> and O<sub>2</sub> volumes add, so the RQ falls between the two values.');
asr(4, 'mitochondrion', 'A mitochondrion can make some of its own proteins.', 'The matrix contains a circular DNA, RNA and ribosomes.', 0, 'DNA, RNA and ribosomes are the components needed for protein synthesis.');
asr(3, 'link reaction', 'The link reaction produces NADH.', 'The link reaction occurs in the cytoplasm.', 2, 'A is true: NAD<sup>+</sup> is reduced when pyruvic acid is decarboxylated. R is false: the link reaction is in the matrix.');
asr(4, 'ETS', 'Complex V makes ATP by directly accepting electrons from cytochrome c.', 'Proton flow through the F<sub>0</sub> channel gives the energy for ATP synthesis.', 3, 'A is false: complex V does not take electrons. The proton flow drives it. R is true.');
asr(3, 'mitochondrion', 'The inner membrane of a mitochondrion is folded into cristae.', 'ATP synthase is made of an F<sub>1</sub> headpiece and an F<sub>0</sub> channel.', 1, 'Both are true, but the structure of ATP synthase does not explain the folding, which gives more surface area.');
asr(5, 'ETS', 'Poisoning of cytochrome c oxidase also stops the Krebs cycle.', 'NAD<sup>+</sup> and FAD cannot be regenerated when the ETS stops.', 0, 'The Krebs cycle needs NAD<sup>+</sup> and FAD. They are regenerated only when the ETS oxidises NADH and FADH<sub>2</sub>.');

// ---- Passages
pass('prpx1', 'Passage: blocking a step of glycolysis', 'In a yeast extract, the step that changes PGAL to BPGA is blocked. Glucose and ATP are supplied. Everything before that step works normally.');
pq('prpx1', 3, 'glycolysis', 'Which compounds will pile up?', 'fructose 1,6-bisphosphate, DHAP and PGAL', ['BPGA and pyruvic acid', 'pyruvic acid and ethanol', 'only glucose'], 'Steps before the block still run, so the sugar phosphates build up. Nothing after the block can be made.');
pq('prpx1', 4, 'glycolysis', 'The net change in ATP for each glucose that enters is', 'a loss of two ATP', ['a gain of two ATP', 'a gain of four ATP', 'no change'], 'Two ATP are spent in the early steps. The two ATP-making steps come after the block, so none is made.');
pq('prpx1', 4, 'fermentation', 'Ethanol production will stop because', 'no pyruvic acid is made, so no acetaldehyde can be formed', ['too much NAD<sup>+</sup> is formed', 'oxygen is not available', 'ATP synthase is blocked'], 'Ethanol comes from pyruvic acid through acetaldehyde.');
pass('prpx2', 'Passage: oxidising different substrates', 'A student adds malic acid, which is oxidised by an NAD-linked enzyme, to a suspension of intact mitochondria with O<sub>2</sub> and ADP. She repeats the test with succinic acid, which is oxidised by an FAD-linked enzyme. Use the NCERT ATP count, and assume the same number of electron pairs reach oxygen from each.');
pq('prpx2', 3, 'ATP accounting', 'The ATP formed in the ETS for each pair of electrons from malic acid is', '3', ['2', '1', '4'], 'The pair of electrons is held by NADH, which gives 3 ATP.');
pq('prpx2', 4, 'ATP accounting', 'For each pair of electrons from succinic acid, the ATP formed is', '2', ['3', '1', '4'], 'The pair is held by FADH<sub>2</sub>, which gives 2 ATP.');
pq('prpx2', 4, 'ETS', 'The smaller yield with succinic acid is best explained by', 'electrons from FADH<sub>2</sub> entering at complex II, bypassing complex I', ['succinic acid not being a respiratory substrate', 'FADH<sub>2</sub> making CO<sub>2</sub>', 'complex IV not being used'], 'Fewer complexes pump protons when electrons enter at complex II, so a smaller gradient and less ATP.');
pass('prpx3', 'Passage: a fermenting culture', 'A yeast culture ferments 0.3 mole of glucose in a sealed flask with no oxygen.');
pq('prpx3', 3, 'fermentation', 'The CO<sub>2</sub> released is', '0.6 mole', ['0.3 mole', '1.8 mole', '0.9 mole'], 'Each glucose gives 2 ethanol and 2 CO<sub>2</sub>. So 0.3 × 2 = 0.6 mole.');
pq('prpx3', 3, 'fermentation', 'The net ATP formed is', '0.6 mole', ['0.3 mole', '11.4 mole', '1.2 mole'], 'Net 2 ATP per glucose in glycolysis. 0.3 × 2 = 0.6 mole.');
pq('prpx3', 4, 'ATP accounting', 'Full aerobic oxidation of the same glucose would give, by the NCERT count,', '11.4 mole of ATP', ['0.6 mole of ATP', '6.8 mole of ATP', '38 mole of ATP'], '0.3 × 38 = 11.4 mole.');

// ---- Integer answers
nt(3, 'ATP accounting', 'How many ATP are made by substrate-level phosphorylation (glycolysis and Krebs cycle together, NCERT count) when 6 glucose molecules are completely oxidised?', 24, 'Per glucose: net 2 in glycolysis + 2 in the Krebs cycle = 4. For 6 glucose: 6 × 4 = 24.');
nt(3, 'ATP accounting', 'How many CO<sub>2</sub> molecules are released by the complete oxidation of 4 glucose molecules?', 24, 'One glucose gives 6 CO<sub>2</sub> (2 in the link reaction and 4 in the Krebs cycle). 4 × 6 = 24.');
nt(4, 'ATP accounting', 'How many NADH are made in the mitochondrial matrix (link reaction and Krebs cycle) when 3 glucose molecules are completely oxidised?', 24, 'Per glucose: 2 (link) + 6 (Krebs) = 8. For 3 glucose: 24.', 'The 2 NADH of glycolysis are made in the cytoplasm and must not be counted.');
nt(4, 'ATP accounting', 'How many ATP are made by oxidative phosphorylation (NCERT count) from 2 glucose molecules?', 68, 'One glucose gives 38 − 4 (substrate level) = 34 by oxidative phosphorylation. 2 × 34 = 68.');
nt(4, 'RQ', 'A seed uses 30 mL of O<sub>2</sub> on carbohydrate (RQ 1) and 20 mL of O<sub>2</sub> on fat (RQ 0.7). The overall RQ multiplied by 100 is', 88, 'CO<sub>2</sub> = 30 × 1 + 20 × 0.7 = 44 mL. O<sub>2</sub> = 50 mL. RQ = 44 ÷ 50 = 0.88. Multiplied by 100: 88.');
nt(4, 'RQ', 'In the oxidation of tripalmitin, 2 mole of C<sub>51</sub>H<sub>98</sub>O<sub>6</sub> need 145 mole of O<sub>2</sub>. How many mole of O<sub>2</sub> are needed for 4 mole of tripalmitin?', 290, 'The ratio is fixed: 4 mole is twice 2 mole, so 2 × 145 = 290.');
nt(4, 'ATP accounting', 'A tissue ferments 12 glucose molecules and then oxidises 3 glucose molecules completely. The total net ATP (NCERT count) is', 138, 'Fermentation: 12 × 2 = 24. Aerobic: 3 × 38 = 114. Total 24 + 114 = 138.');
nt(5, 'ATP accounting', 'Mitochondria completely oxidise 6 pyruvic acid molecules (15 ATP each, NCERT count) and 2 acetyl CoA molecules from fatty acids (12 ATP each). The total ATP is', 114, 'Pyruvic acid: 6 × 15 = 90. Acetyl CoA: 2 × 12 = 24. Total = 114.', 'Acetyl CoA from fat skips the link reaction, so it gives 12 and not 15.');
nt(5, 'RQ', 'In a respirometer, the gas volume falls by 50 mL with KOH present and by 12 mL without KOH. The RQ multiplied by 100 is', 76, 'With KOH: O<sub>2</sub> used = 50 mL. Without KOH: net fall = O<sub>2</sub> used − CO<sub>2</sub> released = 12 mL, so CO<sub>2</sub> = 38 mL. RQ = 38 ÷ 50 = 0.76. Multiplied by 100: 76.');

// ---- More single-answer items
mc(4, 'link reaction', 'Pyruvic acid labelled with <sup>14</sup>C in its carboxyl group is taken through the link reaction. The label first appears in', 'CO<sub>2</sub> released in the link reaction', ['acetyl CoA', 'NADH', 'citric acid'], 'The carboxyl carbon is the one lost as CO<sub>2</sub> in oxidative decarboxylation. Acetyl CoA keeps the other two carbons.', 'Do not confuse with the Krebs cycle, where the carbons from acetyl CoA come off later.');
mc(4, 'ATP accounting', 'The net ATP from glycolysis of one sucrose molecule (NCERT count, with the glucose and fructose both used) is', '4', ['2', '8', '38'], 'Sucrose splits into one glucose and one fructose. Each goes through glycolysis with a net gain of 2 ATP: 2 + 2 = 4.');
mc(4, 'ETS', 'If only NADH supplies electrons, the number of NADH that must be oxidised for each O<sub>2</sub> molecule reduced to water is', '2', ['1', '4', '6'], 'Each O<sub>2</sub> takes 4 electrons. Each NADH gives 2 electrons. So 2 NADH per O<sub>2</sub>.');
mc(4, 'Krebs cycle', 'The ATP made when 1 molecule of fumaric acid is converted to OAA (NCERT count) is', '3', ['2', '1', '6'], 'Fumaric acid → malic acid needs water only. Malic acid → OAA makes 1 NADH, which gives 3 ATP.');
mc(4, 'Krebs cycle', 'Which set has only four-carbon compounds of the Krebs cycle?', 'OAA, succinic acid, fumaric acid, malic acid', ['OAA, citric acid, malic acid, succinic acid', 'succinic acid, α-ketoglutaric acid, fumaric acid, malic acid', 'OAA, isocitric acid, fumaric acid, malic acid'], 'Citric and isocitric acids have 6 C and α-ketoglutaric acid has 5 C. The other four are 4 C acids.');
mc(5, 'RQ', 'Flooded root tissue takes up 6 mL O<sub>2</sub> and releases 30 mL CO<sub>2</sub> in an hour. Its RQ and what it shows are', '5, most of the respiration is anaerobic', ['0.2, mostly fat is used', '1, only carbohydrate is used', '5, protein is the substrate'], 'RQ = 30 ÷ 6 = 5. Far above one with little O<sub>2</sub> use means much CO<sub>2</sub> comes from fermentation.', 'A very high RQ does not mean a particular substrate here.');
mc(5, 'ATP accounting', 'The ATP (NCERT count) from the stage after both ATP investments of glycolysis, per fructose 1,6-bisphosphate, by substrate-level phosphorylation in glycolysis and the Krebs cycle together is', '6', ['4', '2', '8'], 'Glycolysis: 4 ATP are made from the bisphosphate (the 2 invested are already gone). Krebs cycle: 2. Total 6.');
mc(5, 'ATP accounting', 'What fraction of the 38 ATP from one glucose (NCERT count) is made by oxidative phosphorylation?', '34/38', ['4/38', '30/38', '36/38'], 'Substrate-level phosphorylation gives 4 (2 + 2). The other 34 come from the ETS.');

const gens = [
  { id: 'pr-g01', type: 'nat', level: 3, format: 'integer', exams: E, sub: 'ATP accounting',
    make(rng) { const k = int(rng, 2, 9); return { k, q: `How many ATP in total are made when ${k} molecules of glucose are completely oxidised in aerobic respiration (NCERT count: 3 ATP per NADH, 2 per FADH<sub>2</sub>)?`, answer: 38 * k, tol: 0, sol: `One glucose gives 38 ATP: glycolysis 2 + 6, link reaction 6, Krebs cycle 2 + 18 + 4. For ${k} glucose: ${k} × 38 = ${38 * k} ATP.` }; },
    verify(p) { return p.k * (2 + 2 * 3 + 2 * 3 + 2 + 6 * 3 + 2 * 2); } },
  { id: 'pr-g02', type: 'nat', level: 3, format: 'integer', exams: E, sub: 'ATP accounting',
    make(rng) { const k = int(rng, 2, 12); return { k, q: `How many CO<sub>2</sub> are released when ${k} molecules of pyruvic acid are completely oxidised in the mitochondrion?`, answer: 3 * k, tol: 0, sol: `Each pyruvic acid gives 1 CO<sub>2</sub> in the link reaction and 2 in the Krebs cycle = 3. So ${k} × 3 = ${3 * k}.` }; },
    verify(p) { return p.k * 1 + p.k * 2; } },
  { id: 'pr-g03', type: 'nat', level: 3, format: 'integer', exams: E, sub: 'ATP accounting',
    make(rng) { const k = int(rng, 2, 10); return { k, q: `How many NADH are formed in the mitochondrial matrix when ${k} acetyl CoA enter the Krebs cycle?`, answer: 3 * k, tol: 0, sol: `Each turn of the cycle (one acetyl CoA) gives 3 NADH, so ${k} × 3 = ${3 * k}.` }; },
    verify(p) { return p.k + p.k + p.k; } },
  { id: 'pr-g04', type: 'nat', level: 3, format: 'numeric', exams: E, sub: 'RQ', unit: '',
    make(rng) { const o = pick(rng, 20, 80, 10); const r = choose(rng, [0.7, 0.8, 0.9, 1.0, 1.2, 1.4]); const co = +(o * r).toFixed(1); return { o, co, q: `A tissue uses ${o} mL of O<sub>2</sub> and releases ${co} mL of CO<sub>2</sub> in the same time. What is its RQ (to 2 decimal places)?`, answer: +(co / o).toFixed(2), tol: 0.01, sol: `RQ = CO<sub>2</sub> released ÷ O<sub>2</sub> used = ${co} ÷ ${o} = ${(co / o).toFixed(2)}.` }; },
    verify(p) { return p.co / p.o; } },
  { id: 'pr-g05', type: 'nat', level: 4, format: 'integer', exams: E, sub: 'RQ',
    make(rng) { const o = int(rng, 4, 20) * 5; const co = o * 7 / 10; return { o, co, q: `A germinating seed uses ${o} mL of O<sub>2</sub> per hour with an RQ of 0.7. How many mL of CO<sub>2</sub> does it release per hour?`, answer: co, tol: 0, sol: `CO<sub>2</sub> = RQ × O<sub>2</sub> = 0.7 × ${o} = ${co} mL.` }; },
    verify(p) { return p.o - p.o * 0.3; } },
  { id: 'pr-g06', type: 'mcq', level: 3, format: 'single', exams: E, sub: 'ATP accounting',
    make(rng) { const nadh = int(rng, 2, 8); const fad = int(rng, 1, 4); const atp = nadh * 3 + fad * 2; const o = shuffleOpts(rng, `${atp}`, [`${nadh * 3 + fad * 3}`, `${nadh * 2 + fad * 2}`, `${nadh * 2 + fad * 3}`]); return { nadh, fad, q: `A set of reactions produces ${nadh} NADH and ${fad} FADH<sub>2</sub>. How many ATP could the ETS make from them (NCERT count)?`, options: o.options, answer: o.answer, sol: `NADH gives 3 ATP and FADH<sub>2</sub> gives 2 ATP. So ${nadh} × 3 + ${fad} × 2 = ${atp}.` }; },
    verify(p) { return p.options.indexOf(String(p.nadh * 3 + p.fad * 2)); } },
];
export default { topic: 'plant-respiration', groups, items, gens };
